package org.apache.pdfbox.cos;

import org.apache.pdfbox.cos.COSDictionary;
import org.junit.jupiter.api.Test;
import java.io.IOException;
import java.lang.reflect.Field;
import java.util.ArrayList;

class COSDictionarytoString_LogdebugFikaTest {

    @Test
    void testToStringTriggersLogDebug() throws Exception {
        COSDictionary dict = new COSDictionary();

        // Force the toString() method to throw IOException
        // by making getDictionaryString throw IOException
        // We'll use reflection to set up a scenario where getDictionaryString fails
        Field field = COSDictionary.class.getDeclaredField("items");
        field.setAccessible(true);
        field.set(dict, new ArrayList<>() {
            @Override
            public String toString() {
                throw new RuntimeException(new IOException("Test IOException"));
            }
        });

        // Trigger toString which should catch IOException and call LOG.debug
        dict.toString();
    }
}

