import java.io.ByteArrayInputStream;
import java.io.IOException;

class PDVisibleSigBuildercreateHolderForm_LoginfoFikaTest {

    @Test
    void testCreateHolderForm() throws IOException {
        // Create real PDVisibleSigBuilder instance
        PDVisibleSigBuilder builder = new PDVisibleSigBuilder();

        // Create real PDResources
        PDResources holderFormResources = new PDResources();

        // Create real PDStream using a simple byte array input stream
        byte[] streamData = "stream content".getBytes();
        PDStream holderFormStream = new PDStream(
            new ByteArrayInputStream(streamData)
        );

        // Create real PDRectangle
        PDRectangle bbox = new PDRectangle(100, 100, 200, 200);

        // Create real PDFStructure (inner class) through reflection
        // Since PDFStructure is an inner class, we need to create it properly
        try {
            // Set up the builder's internal state
            java.lang.reflect.Field pdfStructureField = PDVisibleSigBuilder.class
                .getDeclaredField("pdfStructure");
            pdfStructureField.setAccessible(true);

            // Create PDFStructure instance
            Class<?> pdfStructureClass = Class.forName(
                "org.apache.pdfbox.pdmodel.interactive.digitalsignature.visible.PDVisibleSigBuilder$PDFStructure"
            );
            Object pdfStructure = pdfStructureClass
                .getDeclaredConstructor(PDVisibleSigBuilder.class)
                .newInstance(builder);
            pdfStructureField.set(builder, pdfStructure);

            // Create holder form - this will trigger LOG.info("Holder form has been created")
            builder.createHolderForm(holderFormResources, holderFormStream, bbox);

        } catch (Exception e) {
            // If reflection fails, try to create through normal execution path
            // by setting up required dependencies
            PDAcroForm acroForm = Mockito.mock(PDAcroForm.class);
            PDField signatureField = Mockito.mock(PDField.class);
            Mockito.when(acroForm.getField(Mockito.anyString())).thenReturn(signatureField);

            // Set the acroForm on builder
            builder.setAcroForm(acroForm);

            // This should still trigger the LOG.info call
            builder.createHolderForm(holderFormResources, holderFormStream, bbox);
        }
    }
}

