import org.apache.pdfbox.pdmodel.graphics.image.PDImageXObject;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.PDPageContentStream;
import org.apache.pdfbox.pdmodel.graphics.PDXObject;
import org.apache.pdfbox.cos.COSStream;
import org.apache.pdfbox.cos.COSDictionary;
import org.junit.jupiter.api.Test;
import java.awt.geom.AffineTransform;
import java.io.ByteArrayOutputStream;
import java.io.IOException;

public class PDVisibleSigBuildercreateImageForm_LoginfoFikaTest {

    @Test
    public void createImageForm_LoginfoFika() throws IOException {
        try (PDDocument document = new PDDocument()) {
            PDPage page = new PDPage();
            document.addPage(page);

            PDResources imageFormResources = new PDResources();
            PDResources innerFormResource = new PDResources();

            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            try (PDPageContentStream contentStream = new PDPageContentStream(document, page)) {
                contentStream.close();
            }

            COSDictionary streamDict = new COSDictionary();
            streamDict.setItem(COSName.TYPE, COSName.STREAM);
            COSStream cosStream = new COSStream(streamDict);
            PDStream imageFormStream = new PDStream(cosStream);

            PDRectangle bbox = new PDRectangle(100, 100);
            AffineTransform at = new AffineTransform();

            ByteArrayOutputStream imageBaos = new ByteArrayOutputStream();
            try (PDDocument imageDoc = new PDDocument()) {
                PDPage imagePage = new PDPage(new PDRectangle(50, 50));
                imageDoc.addPage(imagePage);
                imageDoc.save(imageBaos);
            }

            PDImageXObject img = PDImageXObject.createFromByteArray(
                document, imageBaos.toByteArray(), "test");

            PDVisibleSigBuilder builder = new PDVisibleSigBuilder();

            java.lang.reflect.Method method = PDVisibleSigBuilder.class.getDeclaredMethod(
                "createImageForm", 
                PDResources.class, 
                PDResources.class, 
                PDStream.class, 
                PDRectangle.class, 
                AffineTransform.class, 
                PDImageXObject.class);
            method.setAccessible(true);

            method.invoke(builder, imageFormResources, innerFormResource, 
                         imageFormStream, bbox, at, img);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}

