import java.io.IOException;

public class PDAnnotationPopupgetParent_LogdebugFikaTest {

    @Test
    public void testGetParentTriggersLogDebug() throws Exception {
        PDDocument document = new PDDocument();
        COSDictionary popupDict = new COSDictionary();

        // Create a parent annotation dictionary
        COSDictionary parentDict = new COSDictionary();
        parentDict.setItem(COSName.TYPE, COSName.ANNOT);
        parentDict.setItem(COSName.SUBTYPE, COSName.TEXT);

        // Set the parent reference in the popup dictionary
        popupDict.setItem(COSName.PARENT, parentDict);

