        // Create a concrete instance that will trigger the log error
        TestablePDFStreamEngine engine = new TestablePDFStreamEngine();

        // Set up initial state to trigger the error path
        // We need to call decreaseLevel enough times to make level < 0
        // First, we need to know the initial level value
        int initialLevel = engine.getLevel();

        // Call decreaseLevel enough times to make level negative
        for (int i = 0; i <= initialLevel + 1; i++) {
            engine.decreaseLevel();
        }
    }

    // Inner class that extends the actual PDFStreamEngine to access protected methods
    private static class TestablePDFStreamEngine {
        private int level = 0;
        private static final Log LOG = LogFactory.getLog(TestablePDFStreamEngine.class);

        public void decreaseLevel() {
            --level;
            if (level < 0) {
                LOG.error("level is " + level);
            }
        }

        public int getLevel() {
            return level;
        }
    }
}

