package org.apache.pdfbox.pdmodel.interactive.annotation.handlers;

import org.apache.pdfbox.pdmodel.interactive.annotation.PDAnnotationCaret;
import org.apache.pdfbox.pdmodel.interactive.annotation.PDAppearanceStream;
import org.apache.pdfbox.pdmodel.PDAppearanceContentStream;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.graphics.color.PDColor;
import org.apache.pdfbox.cos.COSName;
import org.apache.pdfbox.pdmodel.interactive.annotation.handlers.PDCaretAppearanceHandler;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import java.io.IOException;

public class PDCaretAppearanceHandlergenerateNormalAppearance_LogerrorFikaTest {

    @Test
    public void testGenerateNormalAppearanceTriggersLogError() throws Exception {
        PDAnnotationCaret mockAnnotation = Mockito.mock(PDAnnotationCaret.class);
        PDAppearanceStream mockAppearanceStream = Mockito.mock(PDAppearanceStream.class);
        PDColor mockColor = Mockito.mock(PDColor.class);

        Mockito.when(mockAnnotation.getConstantOpacity()).thenReturn(0.5f);
        Mockito.when(mockAnnotation.getNormalAppearanceStream()).thenReturn(mockAppearanceStream);
        Mockito.when(mockAnnotation.getCOSObject()).thenReturn(new org.apache.pdfbox.cos.COSDictionary());

        PDRectangle rect = new PDRectangle(100, 100);
        Mockito.when(mockAnnotation.getRectangle()).thenReturn(rect);

        PDCaretAppearanceHandler handler = new PDCaretAppearanceHandler(mockAnnotation);

        java.lang.reflect.Field annotationField = PDCaretAppearanceHandler.class.getDeclaredField("annotation");
        annotationField.setAccessible(true);
        annotationField.set(handler, mockAnnotation);

        java.lang.reflect.Method getColorMethod = PDCaretAppearanceHandler.class.getDeclaredMethod("getColor");
        getColorMethod.setAccessible(true);
        Mockito.when(getColorMethod.invoke(handler)).thenReturn(mockColor);

        java.lang.reflect.Method getNormalAppearanceAsContentStreamMethod = 
            PDCaretAppearanceHandler.class.getDeclaredMethod("getNormalAppearanceAsContentStream");
        getNormalAppearanceAsContentStreamMethod.setAccessible(true);

        PDAppearanceContentStream mockContentStream = Mockito.mock(PDAppearanceContentStream.class);
        Mockito.when(getNormalAppearanceAsContentStreamMethod.invoke(handler))
               .thenReturn(mockContentStream);

        Mockito.doThrow(new IOException("Test exception to trigger Log.error"))
               .when(mockContentStream).close();

        handler.generateNormalAppearance();
    }
}

