 */
public void addOutputIntent(PDOutputIntent outputIntent) {
    COSArray array = root.getCOSArray(COSName.OUTPUT_INTENTS);
    if (array == null) {
        array = new COSArray();
        root.setItem(COSName.OUTPUT_INTENTS, array);
    }
    array.add(outputIntent.getCOSObject());
}

