public class PDDocumentgetVersion_LogerrorFikaTest {

    @Test
    public void testGetVersion() throws Exception {
        // Create a real PDDocument instance
        PDDocument document = new PDDocument();

        // Create a mock PDDocumentCatalog that will trigger the NumberFormatException
        PDDocumentCatalog catalog = Mockito.mock(PDDocumentCatalog.class);
        Mockito.when(catalog.getVersion()).thenReturn("invalid_version");

        // Use reflection to set the catalog in the document
        Field catalogField = PDDocument.class.getDeclaredField("documentCatalog");
        catalogField.setAccessible(true);
