public final Matrix getFontMatrix() {
    if (fontMatrix == null) {
        // PDF specified that Type 1 fonts use a 1000upem matrix, but some fonts specify
        // their own custom matrix anyway, for example PDFBOX-2298
        List<Number> numbers = null;
        try {
            numbers = genericFont.getFontMatrix();
        } catch (IOException e) // PATH: Test should invoke the next Log.debug(...) [step in execution path]
        {
            LOG.debug("Couldn't get font matrix box - returning default value", e);
            fontMatrix = DEFAULT_FONT_MATRIX;
        }
        if ((numbers != null) && (numbers.size() == 6)) {
            fontMatrix = new Matrix(numbers.get(0).floatValue(), numbers.get(1).floatValue(), numbers.get(2).floatValue(), numbers.get(3).floatValue(), numbers.get(4).floatValue(), numbers.get(5).floatValue());
        } else {
            return super.getFontMatrix();
        }
    }
    return fontMatrix;
}

