        // Create new array with mock as last element
        COSArray testArray = new COSArray();
        testArray.add(COSName.getPDFName("Comp1"));
        testArray.add(nonNameBase);

        // Mock color space
        PDColorSpace colorSpace = Mockito.mock(PDColorSpace.class);

        // Create PDColor - this should trigger the warning
        new PDColor(testArray, colorSpace);
    }
}

