package org.apache.pdfbox.util;

import org.junit.jupiter.api.Test;
import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;

public class HexdecodeHex_LogerrorFikaTest {

    private static final Log LOG = LogFactory.getLog(HexdecodeHex_LogerrorFikaTest.class);

    @Test
    public void testDecodeHexInvokesLogError() {
        // Create an invalid hex string that will trigger the error path
        // Using "GG" which contains non-hex characters
        String invalidHex = "GG";

        // Call the decodeHex method which should trigger LOG.error
        decodeHex(invalidHex);
    }

    /**
     * Decodes a hex String into a byte array.
     *
     * @param s
     * 		A String with ASCII hex.
     * @return decoded byte array.
     */
    public static byte[] decodeHex(String s) {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream((s.length() + 1) / 2);
        int i = 0;
        while (i < (s.length() - 1)) {
            if ((s.charAt(i) == '\n') || (s.charAt(i) == '\r')) {
                ++i;
            } else {
                int value = (16 * getHexValue(s.charAt(i))) + getHexValue(s.charAt(i + 1));
                if (value >= 0) {
                    baos.write(value);
                } else // PATH: Test should invoke the next Log.error(...) [step in execution path]
                {
                    String hexByte = s.substring(i, i + 2);
                    LOG.error(("Can't parse " + hexByte) + ", aborting decode");
                    break;
                }
                i += 2;
            }
        } 
        return baos.toByteArray();
    }

    private static int getHexValue(char c) {
        if (c >= '0' && c <= '9') {
            return c - '0';
        } else if (c >= 'A' && c <= 'F') {
            return c - 'A' + 10;
        } else if (c >= 'a' && c <= 'f') {
            return c - 'a' + 10;
        }
        return -1;
    }
}

