        PDPageContentStreamWrapper wrapper = new PDPageContentStreamWrapper(page);
        wrapper.getContentsForRandomAccess();
    }

    private static class PDPageContentStreamWrapper extends PDPage {
        public PDPageContentStreamWrapper(PDPage page) {
            super(page.getCOSObject());
        }

        @Override
        public RandomAccessRead getContentsForRandomAccess() throws IOException {
            COSStream contentStream = getCOSStream(COSName.CONTENTS);
            if (contentStream != null) {
                try {
                    return contentStream.createView();
                } catch (IOException exception) {
                    LOG.warn("skipped malformed content stream");
                    return new RandomAccessReadBuffer(new byte[0]);
                }
            }
