@Override
public String getSuffix() {
    List<COSName> filters = getStream().getFilters();
    if (filters.isEmpty()) {
        return "png";
    } else if (filters.contains(COSName.DCT_DECODE)) {
        return "jpg";
    } else if (filters.contains(COSName.JPX_DECODE)) {
        return "jpx";
    } else if (filters.contains(COSName.CCITTFAX_DECODE)) {
        return "tiff";
    } else if ((filters.contains(COSName.FLATE_DECODE) || filters.contains(COSName.LZW_DECODE)) || filters.contains(COSName.RUN_LENGTH_DECODE)) {
        return "png";
    } else if (filters.contains(COSName.JBIG2_DECODE)) {
        return "jb2";
    } else // PATH: Test should invoke the next Log.warn(...) [step in execution path]
    {
        LOG.warn("getSuffix() returns null, filters: " + filters);
        return null;
    }
}

