package org.apache.pdfbox.pdmodel;

import org.apache.pdfbox.pdmodel.font.PDFont;
import org.apache.pdfbox.pdmodel.font.PDType0Font;
import org.apache.pdfbox.pdmodel.font.Standard14Fonts;
import org.apache.pdfbox.pdmodel.font.PDType1Font;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import java.io.IOException;

public class PDAbstractContentStreamsetFont_LogisDebugEnabledFikaTest {

    @Test
    public void testSetFontInvokesLogIsDebugEnabled() throws IOException {
        PDDocument document = new PDDocument();
        PDPage page = new PDPage(PDRectangle.A4);
        document.addPage(page);

        PDAbstractContentStream stream = new PDAbstractContentStream(
            page.getCOSObject().createOutputStream(),
            page.getResources(),
            document
        ) {};

        PDFont font = Mockito.mock(PDType0Font.class, Mockito.CALLS_REAL_METHODS);
        Mockito.when(font.willBeSubset()).thenReturn(false);
        Mockito.when(font.isEmbedded()).thenReturn(false);
        Mockito.when(font.isStandard14()).thenReturn(false);
        Mockito.when(font.getName()).thenReturn("TestFont");

        PDType0Font type0Font = (PDType0Font) font;
        Mockito.when(type0Font.getGsubData()).thenReturn(org.apache.pdfbox.pdmodel.font.GsubData.NO_DATA_FOUND);
        Mockito.when(type0Font.getCmapLookup()).thenReturn(null);

        stream.setFont(font, 12.0f);

        document.close();
    }
}

