package org.apache.pdfbox.printing;

import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.printing.PDFPrintable;
import org.apache.pdfbox.printing.Scaling;
import org.junit.jupiter.api.Test;
import java.awt.*;
import java.awt.print.PageFormat;
import java.awt.print.Paper;
import java.awt.print.PrinterException;

class PDFPrintableprint_LogwarnFikaTest {

    @Test
    void testPrintInvokesLogWarn() throws Exception {
        // Create a minimal PDF document
        PDDocument document = new PDDocument();
        PDPage page = new PDPage();
        document.addPage(page);

        // Create PDFPrintable instance
        PDFPrintable printable = new PDFPrintable(document);
        printable.setCenter(true);
        printable.setScaling(Scaling.STRETCH_TO_FIT);

        // Create PageFormat with imageable area smaller than page content
        PageFormat pageFormat = new PageFormat();
        Paper paper = new Paper();
        paper.setSize(100, 100); // Small paper size
        paper.setImageableArea(10, 10, 80, 80); // Small imageable area
        pageFormat.setPaper(paper);

        // Create Graphics object
        BufferedImage image = new BufferedImage(100, 100, BufferedImage.TYPE_INT_RGB);
        Graphics2D graphics = image.createGraphics();

        try {
            // This should trigger the negative translation path and invoke LOG.warn()
            printable.print(graphics, pageFormat, 0);
        } catch (PrinterException e) {
            // Expected in some cases, but the LOG.warn() should have been invoked
        } finally {
            graphics.dispose();
            document.close();
        }
    }
}

