public PDFPrintable(PDDocument document) {
    this(document, Scaling.SHRINK_TO_FIT);
}

/**
 * Creates a new PDFPrintable with the given page scaling.
 *
 * @param document
 * 		the document to print
 * @param scaling
 * 		page scaling policy
 */
public PDFPrintable(PDDocument document, Scaling scaling) {
    this(document, scaling, false);
}

/**
 * Creates a new PDFPrintable with the given page scaling and with optional page borders shown.
 *
 * @param document
 * 		the document to print
 * @param scaling
 * 		page scaling policy
 * @param showPageBorder
 * 		true if page borders are to be printed
 */
public PDFPrintable(PDDocument document, Scaling scaling, boolean showPageBorder) {
    this(document, scaling, showPageBorder, RASTERIZE_OFF);
}

/**
 * Creates a new PDFPrintable with the given page scaling and with optional page borders shown.
 * The image will be rasterized at the given DPI before being sent to the printer.
 *
 * @param document
 * 		the document to print
 * @param scaling
 * 		page scaling policy
 * @param showPageBorder
 * 		true if page borders are to be printed
 * @param dpi
 * 		if positive non-zero then the image will be rasterized at the given DPI. If
 * 		set to the special value RASTERIZE_DPI_AUTO, the dpi of the printer will be used.
 * @param center
 * 		true if the content is to be centered on the page (otherwise top-left).
 * @param renderer
 * 		the document renderer. Useful if {@link PDFRenderer} has been subclassed.
 */
public PDFPrintable(PDDocument document, Scaling scaling, boolean showPageBorder, float dpi, boolean center, PDFRenderer renderer) {
    this.pageTree = document.getPages();
    this.renderer = renderer;
    this.scaling = scaling;
    this.showPageBorder = showPageBorder;
    this.dpi = dpi;
    this.center = center;
}

