        // Create mock annotation with necessary setup to reach the IOException block
        PDAnnotationPolyline annotation = Mockito.mock(PDAnnotationPolyline.class);
        PDRectangle rect = new PDRectangle(100, 100, 200, 200);
        float[] pathsArray = {10, 10, 50, 50, 100, 100, 150, 150};

        Mockito.when(annotation.getRectangle()).thenReturn(rect);
        Mockito.when(annotation.getVertices()).thenReturn(pathsArray);
