package org.apache.pdfbox.pdmodel.encryption;

import org.apache.pdfbox.cos.COSArray;
import org.apache.pdfbox.cos.COSName;
import org.apache.pdfbox.pdmodel.encryption.PDEncryption;
import org.apache.pdfbox.pdmodel.encryption.StandardSecurityHandler;
import org.apache.pdfbox.pdmodel.encryption.DecryptionMaterial;
import org.apache.pdfbox.pdmodel.encryption.StandardDecryptionMaterial;
import org.apache.pdfbox.pdmodel.encryption.AccessPermission;
import org.apache.pdfbox.pdmodel.encryption.InvalidPasswordException;
import org.apache.pdfbox.pdmodel.encryption.PDCryptFilterDictionary;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.io.IOException;

public class StandardSecurityHandlerprepareForDecryption_LoginfoFikaTest {

    @Test
    public void testPrepareForDecryptionTriggersLogInfo() throws IOException {
        // Create encryption with revision 4 to hit the target code path
        PDEncryption encryption = Mockito.mock(PDEncryption.class);
        Mockito.when(encryption.getVersion()).thenReturn(4);
        Mockito.when(encryption.getStreamFilterName()).thenReturn(COSName.IDENTITY);
        Mockito.when(encryption.getStringFilterName()).thenReturn(COSName.IDENTITY);
        Mockito.when(encryption.isEncryptMetaData()).thenReturn(false);
        Mockito.when(encryption.getPermissions()).thenReturn(0);
        Mockito.when(encryption.getRevision()).thenReturn(4);
        Mockito.when(encryption.getLength()).thenReturn(40); // Less than 128 to trigger padding

        // Create a real COSArray for document ID
        COSArray documentIDArray = new COSArray();
        documentIDArray.add(COSName.getPDFName("test"));

        // Create real StandardDecryptionMaterial with password
        StandardDecryptionMaterial material = new StandardDecryptionMaterial("test");

        // Create the handler under test
        StandardSecurityHandler handler = new StandardSecurityHandler();

        // Execute the method - this should trigger LOG.info when encryptedKey.length < 16
        handler.prepareForDecryption(encryption, documentIDArray, material);
    }
}

