        Mockito.when(encryption.getVersion()).thenReturn(4);
        Mockito.when(encryption.getStreamFilterName()).thenReturn(COSName.STD_CF);
        Mockito.when(encryption.getStringFilterName()).thenReturn(COSName.STD_CF);
        Mockito.when(encryption.isEncryptMetaData()).thenReturn(false);
        Mockito.when(encryption.getPermissions()).thenReturn(0);
