        Mockito.when(encryption.getCOSObject()).thenReturn(cosDict);

        // Create AESV2 crypt filter dictionary
        PDCryptFilterDictionary cryptFilter = Mockito.mock(PDCryptFilterDictionary.class);
        Mockito.when(cryptFilter.getCryptFilterMethod()).thenReturn(COSName.AESV2);
        Mockito.when(encryption.getStdCryptFilterDictionary()).thenReturn(cryptFilter);

        // Create document ID array
        COSArray documentIDArray = new COSArray();
        documentIDArray.add(COSName.getPDFName("test"));

        // Create decryption material with password
        StandardDecryptionMaterial material = Mockito.mock(StandardDecryptionMaterial.class);
        Mockito.when(material.getPassword()).thenReturn("test");

        // Create handler and call method
        StandardSecurityHandler handler = new StandardSecurityHandler();
        handler.prepareForDecryption(encryption, documentIDArray, material);
    }
}

