package org.apache.pdfbox.pdmodel.interactive.annotation.handlers;

import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.interactive.annotation.PDAnnotationFreeText;
import org.apache.pdfbox.pdmodel.interactive.annotation.PDAppearanceStream;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.io.ByteArrayInputStream;
import java.io.IOException;

public class PDFreeTextAppearanceHandlergenerateNormalAppearance_LogerrorFikaTest {

    @Test
    public void testGenerateNormalAppearance_TriggersLogError() throws Exception {
        // Create a real PDDocument
        PDDocument document = new PDDocument();
        PDPage page = new PDPage(PDRectangle.A4);
        document.addPage(page);

        // Create a real annotation
        PDAnnotationFreeText annotation = new PDAnnotationFreeText();
        annotation.setRectangle(new PDRectangle(100, 100, 200, 50));
        annotation.setContents("Test annotation");

        // Create appearance stream
        PDAppearanceStream appearanceStream = new PDAppearanceStream(document);
        annotation.setNormalAppearanceStream(appearanceStream);

        // Add annotation to page
        page.getAnnotations().add(annotation);

        // Create handler instance
        PDFreeTextAppearanceHandler handler = new PDFreeTextAppearanceHandler();

        // Use reflection to set private fields needed for the method
        try {
            // Set the document field
            var documentField = PDFreeTextAppearanceHandler.class.getDeclaredField("document");
            documentField.setAccessible(true);
            documentField.set(handler, document);

            // Set the annotation field
            var annotationField = PDFreeTextAppearanceHandler.class.getDeclaredField("annotation");
            annotationField.setAccessible(true);
            annotationField.set(handler, annotation);

            // Set font-related fields to avoid NPE
            var fontNameField = PDFreeTextAppearanceHandler.class.getDeclaredField("fontName");
            fontNameField.setAccessible(true);
            fontNameField.set(handler, "Helvetica");

            var fontSizeField = PDFreeTextAppearanceHandler.class.getDeclaredField("fontSize");
            fontSizeField.setAccessible(true);
            fontSizeField.set(handler, 12.0f);

        } catch (Exception e) {
            // If reflection fails, we'll still try to execute the method
        }

        // Create a mock that will throw IOException when getNormalAppearanceAsContentStream is called
        PDFreeTextAppearanceHandler spyHandler = Mockito.spy(handler);

        // Make getNormalAppearanceAsContentStream throw IOException to trigger the catch block
        Mockito.when(spyHandler.getNormalAppearanceAsContentStream(Mockito.anyBoolean()))
               .thenThrow(new IOException("Test exception to trigger Log.error"));

        // Execute the method - this should trigger the IOException and call LOG.error(ex)
        spyHandler.generateNormalAppearance();

        // Close document
        document.close();
    }
}

