        Mockito.when(srcLabels.getCOSArray(COSName.NUMS)).thenReturn(srcNums);
        Mockito.when(destLabels.getCOSArray(COSName.NUMS)).thenReturn(destNums);

        Mockito.when(srcNums.size()).thenReturn(4);
        Mockito.when(destNums.size()).thenReturn(0);

