public class PDShadingType2_AxialShadingPaintmethod_LogFactorygetLogFikaTest {

    @Test
    public void testAxialShadingPaintCreation() throws IOException {
        try (PDDocument document = new PDDocument()) {
            PDPage page = new PDPage(PDRectangle.A4);
            document.addPage(page);

            COSDictionary shadingDict = new COSDictionary();
            shadingDict.setItem(COSName.SHADING_TYPE, COSName.getPDFName("2"));

            COSArray coords = new COSArray();
            coords.addFloat(100f);
            coords.addFloat(100f);
            coords.addFloat(300f);
            coords.addFloat(300f);
            shadingDict.setItem(COSName.COORDS, coords);

            COSArray domain = new COSArray();
            domain.addFloat(0f);
            domain.addFloat(1f);
            shadingDict.setItem(COSName.DOMAIN, domain);

            COSArray functionArray = new COSArray();
            COSDictionary functionDict = new COSDictionary();
            functionDict.setItem(COSName.FUNCTION_TYPE, COSName.getPDFName("2"));

            COSArray c0 = new COSArray();
            c0.addFloat(1f);
            c0.addFloat(0f);
            c0.addFloat(0f);
            functionDict.setItem(COSName.C0, c0);

            COSArray c1 = new COSArray();
            c1.addFloat(0f);
            c1.addFloat(0f);
            c1.addFloat(1f);
            functionDict.setItem(COSName.C1, c1);

            functionDict.setItem(COSName.N, COSName.getPDFName("1"));
            functionArray.add(functionDict);
            shadingDict.setItem(COSName.FUNCTION, functionArray);

            PDShadingType2 shading = new PDShadingType2(shadingDict);

            Rectangle2D bounds = new Rectangle2D.Float(50, 50, 400, 400);
            AffineTransform xform = new AffineTransform();

            AxialShadingPaint paint = new AxialShadingPaint(shading, bounds, xform, PDDeviceRGB.INSTANCE);

            PaintContext context = paint.createContext(
                ColorModel.getRGBdefault(),
                new Rectangle(0, 0, 500, 500),
                bounds,
                xform,
                new RenderingHints(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON)
            );

            context.dispose();
        }
    }
}

