/**
 * Creates a new COSStream using the current configuration for scratch files. Not for public use.
 * Only COSParser should call this method.
 *
 * @param dictionary
 * 		the corresponding dictionary
 * @param startPosition
 * 		the start position within the source
 * @param streamLength
 * 		the stream length
 * @return the new COSStream
 * @throws IOException
 * 		if the random access view can't be read
 */
public COSStream createCOSStream(COSDictionary dictionary, long startPosition, long streamLength) throws IOException {
    COSStream stream = new COSStream(streamCache, parser.createRandomAccessReadView(startPosition, streamLength));
    dictionary.forEach(stream::setItem);
    stream.setKey(dictionary.getKey());
    return stream;
}

