        byte[] pdfData = "%PDF-1.4\n".getBytes();
        ByteArrayInputStream inputStream = new ByteArrayInputStream(pdfData);

        // Create necessary objects for XrefTrailerResolver
        COSDictionary trailer = new COSDictionary();
        COSStream stream = new COSStream(null);

        // Instantiate XrefTrailerResolver which will trigger static initialization
        // including LogFactory.getLog(XrefTrailerResolver.class)
        XrefTrailerResolver resolver = new XrefTrailerResolver();

        // Use the resolver to ensure it's fully initialized
        resolver.setStartxref(0L);
        resolver.nextXrefObj(stream, 0L);
        resolver.setTrailer(trailer);

        // Create and add a COSObject to trigger internal processing
        COSObject cosObject = new COSObject(null);
        resolver.addXrefObject(cosObject);
    }
}

