package org.apache.pdfbox.pdmodel.graphics.image;

import org.junit.jupiter.api.Test;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.PDPageContentStream;
import org.apache.pdfbox.pdmodel.graphics.image.PDImageXObject;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;

class PDInlineImage_SampledImageReadermethod_LogFactorygetLogFikaTest2 {

    @Test
    void testLogFactoryGetLogInvocation() throws IOException {
        // Create a minimal PDF document structure
        try (PDDocument document = new PDDocument()) {
            PDPage page = new PDPage(PDRectangle.A4);
            document.addPage(page);

            // Create a tiny 1x1 pixel image to trigger SampledImageReader usage
            BufferedImage bufferedImage = new BufferedImage(1, 1, BufferedImage.TYPE_INT_RGB);
            bufferedImage.setRGB(0, 0, 0xFFFFFF);

            // Create PDImageXObject which internally uses SampledImageReader
            PDImageXObject pdImage = PDImageXObject.createFromByteArray(
                document,
                createImageData(bufferedImage),
                "test.jpg"
            );

            // Use the image in a content stream to ensure full initialization
            try (PDPageContentStream contentStream = new PDPageContentStream(document, page)) {
                contentStream.drawImage(pdImage, 100, 100);
            }
        }
        // The static initialization of SampledImageReader.LOG will have triggered
        // LogFactory.getLog(SampledImageReader.class) during class loading
    }

    private byte[] createImageData(BufferedImage image) throws IOException {
        // Create minimal JPEG data (just enough to trigger image reading)
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        javax.imageio.ImageIO.write(image, "jpg", baos);
        return baos.toByteArray();
    }
}

