package org.apache.pdfbox.text;

import org.junit.jupiter.api.Test;
import org.apache.pdfbox.contentstream.PDFStreamEngine;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import java.io.ByteArrayInputStream;

public class PDFTextStripper_PDFStreamEnginemethod_LogFactorygetLogFikaTest3 {

    @Test
    public void testPDFStreamEngineInitialization() throws Exception {
        // Create a minimal PDF document to initialize PDFStreamEngine
        byte[] pdfData = "%PDF-1.4\n1 0 obj\n<<>>\nendobj\nxref\n0 2\n0000000000 65535 f \n0000000010 00000 n \ntrailer\n<< /Size 1 /Root 1 0 R >>\nstartxref\n18\n%%EOF".getBytes();

        try (PDDocument document = PDDocument.load(new ByteArrayInputStream(pdfData))) {
            PDPage page = new PDPage();
            document.addPage(page);

            // Create PDFStreamEngine instance - this triggers static initialization
            // which calls LogFactory.getLog(PDFStreamEngine.class)
            PDFStreamEngine engine = new PDFStreamEngine();

            // Process the page to ensure engine is fully initialized
            engine.processPage(page);
        }
    }
}

