                    expectedStartOfNextWordX = EXPECTED_START_OF_NEXT_WORD_X_RESET_VALUE;
                    maxYForLine = MAX_Y_FOR_LINE_RESET_VALUE;
                    maxHeightForLine = MAX_HEIGHT_FOR_LINE_RESET_VALUE;
                    minYTopForLine = MIN_Y_TOP_FOR_LINE_RESET_VALUE;
                }
                // test if our TextPosition starts after a new word would be expected to start
                if (((Float.compare(expectedStartOfNextWordX, EXPECTED_START_OF_NEXT_WORD_X_RESET_VALUE) != 0) && (expectedStartOfNextWordX < positionX)) && // only bother adding a word separator if the last character was not a word separator
                (wordSeparator.isEmpty()// 
                 || ((lastPosition.getTextPosition().getUnicode() != null) && (!lastPosition.getTextPosition().getUnicode().endsWith(wordSeparator))))) {
                    line.add(LineItem.getWordSeparator());
                }
