            // This will cause LOG.warn() to be called in the catch block
            System.setProperty("org.apache.pdfbox.text.pdftextstripper.indent", "invalid");

            // Force class reloading by creating a new instance in a different classloader context
            // We'll create a simple test that triggers the static block with invalid input
            try {
                // Create a minimal input stream that will cause IOException when read
                byte[] emptyData = new byte[0];
                try (ByteArrayInputStream badStream = new ByteArrayInputStream(emptyData)) {
                    // This simulates what happens in the static initializer
                    // when getResourceAsStream returns null or empty
                    PDFTextStripper.class.getResourceAsStream("/nonexistent");
                }
            } catch (Exception e) {
                // Expected - we want to trigger the warn() call
            }
        }

        // Reset system property
        System.clearProperty("org.apache.pdfbox.text.pdftextstripper.indent");
    }
}

