package org.apache.pdfbox.text;

import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.junit.jupiter.api.Test;
import java.io.ByteArrayInputStream;
import java.io.IOException;

class PDFTextStrippermethod_LogwarnFikaTest3 {

    @Test
    void testLogWarnInvocation() throws IOException {
        // Create a minimal PDF document to process
        try (PDDocument document = new PDDocument()) {
            PDPage page = new PDPage(PDRectangle.A4);
            document.addPage(page);

            PDFTextStripper stripper = new PDFTextStripper();

            // Set system property to trigger the static initializer block
            // that contains the target Log.warn() call
            System.setProperty("pdftextstripper.indent", "invalid_float");
            System.setProperty("pdftextstripper.drop", "invalid_float");

            try {
                // Create a new instance to trigger static initialization
                // with the invalid system properties
                PDFTextStripper anotherStripper = new PDFTextStripper();

                // Try to extract text - this will trigger various code paths
                // including the static initializer that may call Log.warn()
                stripper.getText(document);
            } finally {
                // Clean up system properties
                System.clearProperty("pdftextstripper.indent");
                System.clearProperty("pdftextstripper.drop");
            }
        }
    }
}

