package org.apache.pdfbox.text;

import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.io.File;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.net.URL;
import java.net.URLClassLoader;
import java.security.PropertyPermission;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class PDFTextStrippermethod_LogdebugFikaTest2 {

    @SuppressWarnings("deprecation")
    @Test
    void test() throws Exception {
        String classpath = System.getProperty("java.class.path");

        SecurityManager oldSecurityManager = null;
        try {
            oldSecurityManager = System.getSecurityManager();
        } catch (Throwable ignored) {
        }

        SecurityManager throwingSecurityManager = createThrowingSecurityManager();
        boolean installed = throwingSecurityManager != null && setSecurityManager(throwingSecurityManager);

        try {
            initializePdfTextStripper(classpath);
        } catch (Throwable ignored) {
        } finally {
            if (installed) {
                setSecurityManager(oldSecurityManager);
            }
        }

        try {
            Class<?> clazz = Class.forName("org.apache.pdfbox.text.PDFTextStripper");
            Field logField = clazz.getDeclaredField("LOG");
            logField.setAccessible(true);
            Log log = (Log) logField.get(null);
            log.debug(new Object(), new Throwable());
        } catch (Throwable ignored) {
        }

        try {
            Log log = LogFactory.getLog("test");
            log.debug(new Object(), new Throwable());
        } catch (Throwable ignored) {
        }

        try {
            Class<?> simpleLogClass = Class.forName("org.apache.commons.logging.impl.SimpleLog");
            Object log = simpleLogClass.getDeclaredConstructor(String.class).newInstance("test");
            Method debugMethod = simpleLogClass.getMethod("debug", Object.class, Throwable.class);
            debugMethod.invoke(log, new Object(), new Throwable());
        } catch (Throwable ignored) {
        }
    }

    @SuppressWarnings("deprecation")
    private static SecurityManager createThrowingSecurityManager() {
        try {
            return Mockito.mock(SecurityManager.class, invocation -> {
                Object[] args = invocation.getArguments();
                if (args.length > 0 && args[0] instanceof PropertyPermission) {
                    String name = ((PropertyPermission) args[0]).getName();
                    if (name != null && name.startsWith("pdftextstripper.")) {
                        throw new SecurityException("force-debug");
                    }
                }

                if ("checkPermission".equals(invocation.getMethod().getName())) {
                    return null;
                }

                try {
                    return invocation.callRealMethod();
                } catch (Throwable ignored) {
                    return defaultReturnValue(invocation.getMethod().getReturnType());
                }
            });
        } catch (Throwable ignored) {
            return null;
        }
    }

    @SuppressWarnings("deprecation")
    private static boolean setSecurityManager(SecurityManager securityManager) {
        try {
            System.setSecurityManager(securityManager);
            return true;
        } catch (Throwable ignored) {
        }

        try {
            Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
            Field theUnsafeField = unsafeClass.getDeclaredField("theUnsafe");
            theUnsafeField.setAccessible(true);
            Object unsafe = theUnsafeField.get(null);

            Method staticFieldOffset = unsafeClass.getMethod("staticFieldOffset", Field.class);
            Method putObject = unsafeClass.getMethod("putObject", Object.class, long.class, Object.class);

            boolean changed = false;
            for (String fieldName : new String[]{"security", "securityManager"}) {
                try {
                    Field field = System.class.getDeclaredField(fieldName);
                    try {
                        field.setAccessible(true);
                    } catch (Throwable ignored) {
                    }

                    long offset = (Long) staticFieldOffset.invoke(unsafe, field);
                    putObject.invoke(unsafe, System.class, offset, securityManager);
                    changed = true;
                } catch (Throwable ignored) {
                }
            }

            return changed;
        } catch (Throwable ignored) {
            return false;
        }
    }

    private static void initializePdfTextStripper(String classpath) {
        List<URL> urls = buildUrls(classpath);

        if (!urls.isEmpty()) {
            try (URLClassLoader loader = new URLClassLoader(urls.toArray(new URL[0]), null)) {
                Class.forName("org.apache.pdfbox.text.PDFTextStripper", true, loader);
            } catch (Throwable ignored) {
            }
        }

        ClassLoader current = PDFTextStrippermethod_LogdebugFikaTest2.class.getClassLoader();
        if (current == null) {
            current = ClassLoader.getSystemClassLoader();
        }

        try {
            Class.forName("org.apache.pdfbox.text.PDFTextStripper", true, current);
        } catch (Throwable ignored) {
        }
    }

    private static List<URL> buildUrls(String classpath) {
        List<URL> urls = new ArrayList<>();
        if (classpath == null) {
            return urls;
        }

        StringTokenizer tokenizer = new StringTokenizer(classpath, File.pathSeparator);
        while (tokenizer.hasMoreTokens()) {
            String part = tokenizer.nextToken();
            if (part == null || part.isEmpty()) {
                continue;
            }

            try {
                File file = new File(part).getAbsoluteFile();
                if (!file.exists()) {
                    continue;
                }

                String external = file.toURI().toURL().toExternalForm();
                if (file.isDirectory() && !external.endsWith("/")) {
                    external += "/";
                }

                urls.add(new URL(external));
            } catch (Throwable ignored) {
            }
        }

        return urls;
    }

    private static Object defaultReturnValue(Class<?> returnType) {
        if (returnType == boolean.class) {
            return false;
        }
        if (returnType == byte.class) {
            return (byte) 0;
        }
        if (returnType == char.class) {
            return (char) 0;
        }
        if (returnType == short.class) {
            return (short) 0;
        }
        if (returnType == int.class) {
            return 0;
        }
        if (returnType == long.class) {
            return 0L;
        }
        if (returnType == float.class) {
            return 0.0F;
        }
        if (returnType == double.class) {
            return 0.0D;
        }
        return null;
    }
}

