class PDImageXObject_SampledImageReadermethod_LogFactorygetLogFikaTest3 {

    @Test
    void testLogFactoryGetLogInvocation() throws IOException {
        // Create a minimal valid PNG image data
        byte[] pngData = createMinimalPng();

        try (PDDocument document = new PDDocument()) {
            // This will trigger static initialization of SampledImageReader
            // which calls LogFactory.getLog(SampledImageReader.class)
            PDImageXObject.createFromByteArray(document, pngData, "test.png");
        }
    }

    private byte[] createMinimalPng() {
        // Minimal valid PNG file (1x1 black pixel)
        return new byte[] {
            (byte) 0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A, // PNG signature
            0x00, 0x00, 0x00, 0x0D, // IHDR chunk length
            0x49, 0x48, 0x44, 0x52, // "IHDR"
            0x00, 0x00, 0x00, 0x01, // width = 1
            0x00, 0x00, 0x00, 0x01, // height = 1
            0x08, // bit depth = 8
            0x02, // color type = RGB
            0x00, // compression method = 0
            0x00, // filter method = 0
            0x00, // interlace method = 0
            (byte) 0xAE, 0x42, 0x60, (byte) 0x82, // CRC
            0x00, 0x00, 0x00, 0x0A, // IDAT chunk length
            0x49, 0x44, 0x41, 0x54, // "IDAT"
            0x78, 0x01, 0x63, 0x00, 0x00, 0x00, 0x02, 0x00, 0x01, // compressed data
            (byte) 0xE6, 0x0D, (byte) 0x9E, 0x7A, // CRC
            0x00, 0x00, 0x00, 0x00, // IEND chunk length
            0x49, 0x45, 0x4E, 0x44, // "IEND"
            (byte) 0xAE, 0x42, 0x60, (byte) 0x82  // CRC
        };
    }
}

