package org.apache.pdfbox.pdmodel.graphics.shading;

import org.apache.pdfbox.pdmodel.graphics.shading.Type1ShadingPaint;
import org.apache.pdfbox.pdmodel.graphics.shading.PDShadingType1;
import org.apache.pdfbox.cos.COSArray;
import org.apache.pdfbox.cos.COSFloat;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.util.Matrix;
import java.awt.ColorModel;
import java.awt.color.ColorSpace;
import java.awt.image.ColorModel;
import java.awt.image.ComponentColorModel;
import java.awt.geom.AffineTransform;
import java.awt.geom.NoninvertibleTransformException;
import java.io.IOException;
import org.junit.jupiter.api.Test;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

class Type1ShadingPaint_Type1ShadingContextmethod_LogerrorFikaTest {

    @Test
    void testLogErrorInvocation() throws IOException {
        // Create a PDShadingType1 that will cause NoninvertibleTransformException
        PDShadingType1 shading = mock(PDShadingType1.class);

        // Setup domain to avoid NPE
        COSArray domainArray = new COSArray();
        domainArray.add(new COSFloat(0));
        domainArray.add(new COSFloat(1));
        domainArray.add(new COSFloat(0));
        domainArray.add(new COSFloat(1));
        PDRectangle domainRect = new PDRectangle(domainArray);
        when(shading.getDomain()).thenReturn(domainRect);

        // Create a non-invertible matrix to trigger the exception
        Matrix nonInvertibleMatrix = new Matrix(0, 0, 0, 0, 0, 0);
        when(shading.getMatrix()).thenReturn(nonInvertibleMatrix);

        // Create other required parameters
        ColorSpace cs = ColorSpace.getInstance(ColorSpace.CS_sRGB);
        ColorModel colorModel = new ComponentColorModel(cs, false, false, 
            ColorModel.OPAQUE, cs.getDataLayout(null));
        AffineTransform xform = new AffineTransform();
        Matrix matrix = new Matrix();

        // This will trigger NoninvertibleTransformException and invoke Log.error
        new Type1ShadingPaint.Type1ShadingContext(shading, colorModel, xform, matrix);
    }
}

