        }
        return ((PDAnnotationMarkup) (ann));
    } catch (IOException ioe) {
        LOG.debug("An exception while trying to get the parent markup - ignoring", ioe);
        // Couldn't construct the annotation, so return null i.e. do nothing
        return null;
    }
}

