/**
 * This will output this string as a PDF object.
 *
 * @param output
 * 		The stream to write to.
 * @throws IOException
 * 		If there is an error writing to the stream.
 */
public void writePDF(OutputStream output) throws IOException {
    output.write('/');
    byte[] bytes = getName().getBytes(StandardCharsets.UTF_8);
    for (byte b : bytes) {
        int current = b & 0xff;
        // be more restrictive than the PDF spec, "Name Objects", see PDFBOX-2073
        if ((((((((((((current >= 'A') && (current <= 'Z')) || ((current >= 'a') && (current <= 'z'))) || ((current >= '0') && (current <= '9'))) || (current == '+')) || (current == '-')) || (current == '_')) || (current == '@')) || (current == '*')) || (current == '$')) || (current == ';')) || (current == '.')) {
            output.write(current);
        } else {
            output.write('#');
            Hex.writeHexByte(b, output);
        }
    }
}

