@Override
public float getStringWidth(String string) throws IOException {
    if (cffFont == null) {
        LOG.warn("No embedded CFF font, returning 0");
        return 0;
    }
    float width = 0;
    for (int i = 0; i < string.length(); i++) {
        int codePoint = string.codePointAt(i);
        String name = getGlyphList().codePointToName(codePoint);
        if (!cffFont.hasGlyph(name)) {
            throw new IllegalArgumentException(String.format("U+%04X ('%s') is not available in font %s", codePoint, name, getName()));
        }
        width += cffFont.getType1CharString(name).getWidth();
    }
    return width;
}

