private BoundingBox generateBoundingBox() {
    if (getFontDescriptor() != null) {
        PDRectangle bbox = getFontDescriptor().getFontBoundingBox();
        if ((bbox != null) && ((((Float.compare(bbox.getLowerLeftX(), 0) != 0) || (Float.compare(bbox.getLowerLeftY(), 0) != 0)) || (Float.compare(bbox.getUpperRightX(), 0) != 0)) || (Float.compare(bbox.getUpperRightY(), 0) != 0))) {
            return new BoundingBox(bbox.getLowerLeftX(), bbox.getLowerLeftY(), bbox.getUpperRightX(), bbox.getUpperRightY());
        }
    }
    try {
        return cidFont != null ? cidFont.getFontBBox() : t1Font.getFontBBox();
    } catch (IOException e) // PATH: Test should invoke the next Log.debug(...) [step in execution path]
    {
        LOG.debug("Couldn't get font bounding box - returning default value", e);
        return new BoundingBox();
    }
}

