package org.apache.pdfbox.rendering;

import org.junit.jupiter.api.Test;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;

class PageDrawermethod_LogFactorygetLogFikaTest {

    @Test
    void testLogFactoryGetLogInvocation() throws IOException {
        // Create minimal PDF document to instantiate PageDrawer
        byte[] pdfData = "%PDF-1.4\n1 0 obj\n<<>>\nendobj\ntrailer\n<<>>\n%%EOF".getBytes();

        try (PDDocument document = PDDocument.load(new ByteArrayInputStream(pdfData))) {
            PDPage page = new PDPage(PDRectangle.A4);
            document.addPage(page);

            // Create PageDrawer instance - this triggers static initialization
            // which calls LogFactory.getLog(PageDrawer.class)
            PageDrawer drawer = new PageDrawer(null);

            // Trigger some method to ensure class is fully initialized
            BufferedImage image = new BufferedImage(100, 100, BufferedImage.TYPE_INT_RGB);
            drawer.drawPage(null, image, 72);
        }
    }
}

