        // or access a static member. This will trigger the LOG.debug call
        // when the IOException is thrown in the static block.

        // Accessing the class to trigger static initialization
        // The exception in the static block will be caught and logged
        Class<?> clazz = PDDocument.class;

        // Create an instance to ensure class is fully initialized
        // The static block executes during class loading, which happens
        // before instance creation, but creating an instance ensures
        // the class is loaded if it wasn't already
        try (PDDocument document = new PDDocument()) {
            // No assertions needed - just triggering the static initialization
            // which contains the target LOG.debug() call
        }
    }
}

