package org.apache.pdfbox.contentstream;

import org.apache.pdfbox.contentstream.PDFStreamEngine;
import org.apache.pdfbox.pdmodel.font.PDFont;
import org.apache.pdfbox.pdmodel.graphics.state.PDGraphicsState;
import org.apache.pdfbox.pdmodel.graphics.state.PDTextState;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;

import static org.mockito.Mockito.when;

public class PDFStreamEngineshowText_LogwarnFikaTest {

    @Test
    public void testShowText() throws IOException {
        PDFStreamEngine engine = Mockito.spy(PDFStreamEngine.class);

        PDGraphicsState graphicsState = Mockito.mock(PDGraphicsState.class);
        PDTextState textState = Mockito.mock(PDTextState.class);

        when(engine.getGraphicsState()).thenReturn(graphicsState);
        when(graphicsState.getTextState()).thenReturn(textState);
        when(textState.getFont()).thenReturn(null);

        when(textState.getFontSize()).thenReturn(12.0f);
        when(textState.getHorizontalScaling()).thenReturn(100.0f);
        when(textState.getCharacterSpacing()).thenReturn(0.0f);
        when(textState.getRise()).thenReturn(0.0f);
        when(textState.getWordSpacing()).thenReturn(0.0f);

        when(graphicsState.getTextMatrix()).thenReturn(new org.apache.pdfbox.util.Matrix());
        when(graphicsState.getCurrentTransformationMatrix()).thenReturn(new org.apache.pdfbox.util.Matrix());

        PDFont defaultFont = Mockito.mock(PDFont.class);
        when(engine.getDefaultFont()).thenReturn(defaultFont);
        when(defaultFont.isVertical()).thenReturn(false);

        byte[] testData = new byte[]{32};
        when(defaultFont.readCode(Mockito.any(InputStream.class))).thenReturn(32);

        engine.showText(testData);
    }
}

