        PDRectangle pageSize = new PDRectangle(100, 100);
        PDRectangle bbox = new PDRectangle(0, 0, 50, 50);

        when(form.getOptionalContent()).thenReturn(null);
        when(form.getBBox()).thenReturn(bbox);

        drawer.pageSize = pageSize;
        drawer.xformScalingFactorX = 1.0f;
        drawer.xformScalingFactorY = 1.0f;
        drawer.xform = new AffineTransform();
        drawer.flipTG = false;

        GraphicsState graphicsState = new GraphicsState();
        graphicsState.setSoftMask(null);
        drawer.setGraphicsState(graphicsState);

        when(graphics.getTransform()).thenReturn(new AffineTransform());

        drawer.showTransparencyGroupOnGraphics(form, graphics);
    }

    private static class PageDrawer {
        protected PDRectangle pageSize;
        protected float xformScalingFactorX;
        protected float xformScalingFactorY;
        protected AffineTransform xform;
        protected boolean flipTG;
        protected GraphicsState graphicsState;
        protected final org.apache.commons.logging.Log LOG = org.apache.commons.logging.LogFactory.getLog(PageDrawer.class);

        protected void showTransparencyGroupOnGraphics(PDTransparencyGroup form, Graphics2D graphics) throws IOException {
            if (isHiddenOCG(form.getOptionalContent())) {
                return;
            }
            if (!isContentRendered()) {
                return;
            }
            TransparencyGroup group = new TransparencyGroup(form, false, getGraphicsState().getCurrentTransformationMatrix(), null);
            BufferedImage image = group.getImage();
            if (image == null) {
                return;
            }
            graphics.setComposite(getGraphicsState().getNonStrokingJavaComposite());
            setClip();
            AffineTransform savedTransform = graphics.getTransform();
            AffineTransform transform = new AffineTransform(xform);
            transform.scale(1.0 / xformScalingFactorX, 1.0 / xformScalingFactorY);
            graphics.setTransform(transform);
            PDRectangle bbox = group.getBBox();
            float x = bbox.getLowerLeftX() - pageSize.getLowerLeftX();
            float y = pageSize.getUpperRightY() - bbox.getUpperRightY();
            if (flipTG) {
                graphics.translate(0, image.getHeight());
                graphics.scale(1, -1);
            } else {
                graphics.translate(x * xformScalingFactorX, y * xformScalingFactorY);
            }
            PDSoftMask softMask = getGraphicsState().getSoftMask();
            if (softMask != null) {
                Paint awtPaint = new TexturePaint(image, new Rectangle2D.Float(0, 0, image.getWidth(), image.getHeight()));
                awtPaint = applySoftMaskToPaint(awtPaint, softMask);
                graphics.setPaint(awtPaint);
                graphics.fill(new Rectangle2D.Float(0, 0, bbox.getWidth() * xformScalingFactorX, bbox.getHeight() * xformScalingFactorY));
            } else {
                try {
                    graphics.drawImage(image, null, null);
                } catch (InternalError ie) {
                    LOG.error("Exception drawing image, see JDK-6689349, " + "try rendering into a BufferedImage instead", ie);
                }
            }
            graphics.setTransform(savedTransform);
        }

        protected boolean isHiddenOCG(Object optionalContent) {
            return false;
        }

        protected boolean isContentRendered() {
            return true;
        }

        protected void setClip() {
        }

        protected Paint applySoftMaskToPaint(Paint paint, PDSoftMask softMask) {
            return paint;
        }

        protected GraphicsState getGraphicsState() {
            return graphicsState;
        }

        protected void setGraphicsState(GraphicsState graphicsState) {
            this.graphicsState = graphicsState;
        }
    }

    private static class GraphicsState {
        private PDSoftMask softMask;

        public java.awt.Composite getNonStrokingJavaComposite() {
            return java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER);
        }

        public AffineTransform getCurrentTransformationMatrix() {
            return new AffineTransform();
        }

        public PDSoftMask getSoftMask() {
            return softMask;
        }

        public void setSoftMask(PDSoftMask softMask) {
            this.softMask = softMask;
        }
    }

    private static class TransparencyGroup {
        private final PDTransparencyGroup form;
        private final boolean flag;
        private final AffineTransform transform;
        private final Object obj;

        public TransparencyGroup(PDTransparencyGroup form, boolean flag, AffineTransform transform, Object obj) {
            this.form = form;
            this.flag = flag;
            this.transform = transform;
            this.obj = obj;
        }

        public BufferedImage getImage() {
            return new BufferedImage(10, 10, BufferedImage.TYPE_INT_ARGB);
        }

        public PDRectangle getBBox() {
            return form.getBBox();
        }
    }
}

