/**
 * Creates a Type 1 font from a Font dictionary in a PDF.
 *
 * @param fontDictionary
 * 		font dictionary.
 * @throws IOException
 * 		if there was an error initializing the font.
 * @throws IllegalArgumentException
 * 		if /FontFile3 was used.
