public BufferedImage getImage(Rectangle region, int subsampling) throws IOException // PATH: Test should invoke the next PDImageXObject.initJPXValues(...) [step in execution path]
{
    if (((region == null) && (subsampling == cachedImageSubsampling)) && (cachedImage != null)) {
        BufferedImage cached = cachedImage.get();
        if (cached != null) {
            return cached;
        }
    }
    initJPXValues();
    // get RGB image w/o reference because applyMask might modify it, take long time and a lot of memory.
    final BufferedImage image;
    final PDImageXObject softMask = getSoftMask();
    final PDImageXObject mask = getMask();
    if (jpxSMask != null) {
        // PDFBOX-5657: handle JPEG2000 SMaskInData
        image = applyMask(SampledImageReader.getRGBImage(this, region, subsampling, getColorKeyMask()), jpxSMask, false, true, null);
    } else if (softMask != null) {
        image = applyMask(SampledImageReader.getRGBImage(this, region, subsampling, getColorKeyMask()), softMask.getOpaqueImage(region, subsampling), softMask.getInterpolate(), true, extractMatte(softMask));
    } else if ((mask != null) && mask.isStencil()) {
        image = applyMask(SampledImageReader.getRGBImage(this, region, subsampling, getColorKeyMask()), mask.getOpaqueImage(region, subsampling), mask.getInterpolate(), false, null);
    } else {
        image = SampledImageReader.getRGBImage(this, region, subsampling, getColorKeyMask());
    }
    if ((region == null) && (subsampling <= cachedImageSubsampling)) {
        // only cache full-image renders, and prefer lower subsampling frequency, as lower
        // subsampling means higher quality and longer render times.
        cachedImageSubsampling = subsampling;
        cachedImage = new SoftReference<>(image);
    }
    return image;
}

