 * 		he access permissions of the pdf
 */
public PDDocument(COSDocument doc, RandomAccessRead source, AccessPermission permission) {
    document = doc;
    document.getDocumentState().setParsing(false);
    pdfSource = source;
    accessPermission = permission;
}

