    private org.apache.commons.logging.Log LOG;

    @Test
    void testHasNoFollowingBinData() throws IOException {
        PDFStreamParser parser = new PDFStreamParser(createMockInputStream());

        // Use reflection to set the private LOG field
        try {
            java.lang.reflect.Field logField = PDFStreamParser.class.getDeclaredField("LOG");
            logField.setAccessible(true);
            logField.set(parser, LOG);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Invoke the private method
        try {
            java.lang.reflect.Method method = PDFStreamParser.class.getDeclaredMethod("hasNoFollowingBinData");
            method.setAccessible(true);
            method.invoke(parser);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private InputStream createMockInputStream() {
        return new InputStream() {
            private final byte[] data = "EI Q".getBytes(java.nio.charset.StandardCharsets.US_ASCII);
            private int position = 0;
            private final int MAX_BIN_CHAR_TEST_LENGTH = 10;

            @Override
            public int read(byte[] b, int off, int len) throws IOException {
                int bytesToCopy = Math.min(len, data.length - position);
                if (bytesToCopy <= 0) {
                    return -1;
                }
                System.arraycopy(data, position, b, off, bytesToCopy);
                position += bytesToCopy;
                return bytesToCopy;
            }

            @Override
            public int read() throws IOException {
                if (position >= data.length) {
                    return -1;
                }
                return data[position++] & 0xFF;
            }

            public void rewind(int n) {
                position = Math.max(0, position - n);
            }

            public long getPosition() {
                return position;
            }
        };
    }
}

