@Override
public void beginMarkedContentSequence(COSName tag, COSDictionary properties) {
    if (nestedHiddenOCGCount > 0) {
        nestedHiddenOCGCount++;
        return;
    }
    if (properties == null) {
        return;
    }
    if (isHiddenOCG(PDPropertyList.create(properties))) {
        nestedHiddenOCGCount = 1;
    }
}

