    output.write(getArticleEnd());
}

@Override
public void endMarkedContentSequence() {
    PDMarkedContent markedContent = currentMarkedContents.peek();
    if (markedContent != null) {
        if (markedContent.getActualText() != null) {
            actualText = null;
        }
        currentMarkedContents.pop();
    }
