/**
 * Compute the owner entry in the encryption dictionary.
 *
 * @param ownerPassword
 * 		The plaintext owner password.
 * @param userPassword
 * 		The plaintext user password.
 * @param encRevision
 * 		The revision number of the encryption algorithm.
 * @param length
 * 		The length of the encryption key.
 * @return The o entry of the encryption dictionary.
 * @throws IOException
 * 		if the owner password could not be computed
 */
public byte[] computeOwnerPassword(byte[] ownerPassword, byte[] userPassword, int encRevision, int length) throws IOException {
    if ((REVISION_2 == encRevision) && (length != 5)) {
        throw new IOException("Expected length=5 actual=" + length);
    }
    byte[] rc4Key = computeRC4key(ownerPassword, encRevision, length);
    // PATH: Test should invoke the next StandardSecurityHandler.truncateOrPad(...) [step in execution path]
    byte[] paddedUser = truncateOrPad(userPassword);
    ByteArrayOutputStream encrypted = new ByteArrayOutputStream();
    encryptDataRC4(rc4Key, new ByteArrayInputStream(paddedUser), encrypted);
    if ((encRevision == REVISION_3) || (encRevision == REVISION_4)) {
        byte[] iterationKey = new byte[rc4Key.length];
        for (int i = 1; i < 20; i++) {
            System.arraycopy(rc4Key, 0, iterationKey, 0, rc4Key.length);
            for (int j = 0; j < iterationKey.length; j++) {
                iterationKey[j] = ((byte) (iterationKey[j] ^ ((byte) (i))));
            }
