        // This will trigger the LOG.info() call in the constructor
        java.lang.reflect.Field fontInfoListField = FileSystemFontProvider.class
                .getDeclaredField("fontInfoList");
        fontInfoListField.setAccessible(true);
        List<?> fontInfoList = (List<?>) fontInfoListField.get(provider);

