            if (cachedInfos == null || cachedInfos.isEmpty()) {
                // This will cause the constructor execution path to reach LOG.info()
                java.lang.reflect.Method scanFontsMethod = FileSystemFontProvider.class
                        .getDeclaredMethod("scanFonts", List.class);
                scanFontsMethod.setAccessible(true);
