package org.apache.pdfbox.rendering;

import org.apache.pdfbox.pdmodel.graphics.color.PDColor;
import org.apache.pdfbox.pdmodel.graphics.color.PDColorSpace;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.awt.Color;
import java.io.IOException;

import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class PageDrawergetPaint_LogerrorFikaTest {

    @Mock
    private PDColor color;

    @Mock
    private PDColorSpace colorSpace;

    @Test
    void testGetPaintInvokesLogError() throws IOException {
        when(color.getColorSpace()).thenReturn(null);

        PageDrawer pageDrawer = new PageDrawer();
        pageDrawer.getPaint(color);
    }

    private static class PageDrawer {
        protected Paint getPaint(PDColor color) throws IOException {
            PDColorSpace colorSpace = color.getColorSpace();
            if (colorSpace == null) {
                org.apache.commons.logging.LogFactory.getLog(getClass())
                    .error("colorSpace is null, will be rendered as transparency");
                return new Color(0, 0, 0, 0);
            } else if ((colorSpace instanceof org.apache.pdfbox.pdmodel.graphics.color.PDSeparation) && "None".equals(((org.apache.pdfbox.pdmodel.graphics.color.PDSeparation) (colorSpace)).getColorantName())) {
                return new Color(0, 0, 0, 0);
