        }
        // "an initialization vector of zero"
        cipher.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(getEncryptionKey(), "AES"), new IvParameterSpec(new byte[16]));
        byte[] permsEnc = cipher.doFinal(perms);
        encryptionDictionary.setPerms(permsEnc);
    } catch (GeneralSecurityException e) // PATH: Test should invoke the next StandardSecurityHandler.logIfStrongEncryptionMissing(...) [step in execution path]
