        org.apache.pdfbox.pdfparser.PDFObjectStreamParser streamParser = 
            Mockito.mock(org.apache.pdfbox.pdfparser.PDFObjectStreamParser.class);
        Mockito.when(streamParser.parseAllObjects()).thenThrow(new IOException("Test exception"));

        // Use PowerMockito to mock the constructor call (since we can't control the actual instantiation)
        // We'll use Mockito's construction mocking via inline mock maker
        try (org.mockito.MockedConstruction<org.apache.pdfbox.pdfparser.PDFObjectStreamParser> mocked = 
                Mockito.mockConstruction(org.apache.pdfbox.pdfparser.PDFObjectStreamParser.class,
                    (mock, context) -> {
                        Mockito.when(mock.parseAllObjects()).thenThrow(new IOException("Test exception"));
                    })) {

            // Call the method with parameters that will trigger the error path
            parser.parseObjectStreamObject(1L, new COSObjectKey(2L, 3));
        }
    }
