        shape = area;
    } else {
        shape = linePath;
    }
    if (isContentRendered() && (!shape.getPathIterator(null).isDone())) {
        // creating Paint is sometimes a costly operation, so avoid if possible
        graphics.setPaint(getNonStrokingPaint());
