    private static class FontInfo {
        private FontFormat format;

        public FontFormat getFormat() {
            return format;
        }

        public void setFormat(FontFormat format) {
            this.format = format;
        }
    }

    private enum FontFormat {
        TYPE1, TRUETYPE, TYPE3
    }

    private static class TestFontMapper {
        private final Map<String, FontInfo> fontInfoByName = new HashMap<>();
        private static final Log LOG = LogFactory.getLog(TestFontMapper.class);

        private FontInfo getFont(FontFormat format, String postScriptName) {
            int index = postScriptName.indexOf('+');
            if (index > (-1)) {
                postScriptName = postScriptName.substring(index + 1);
            }
            FontInfo info = fontInfoByName.get(postScriptName.toLowerCase(Locale.ENGLISH));
            if ((info != null) && (info.getFormat() == format)) {
                if (LOG.isDebugEnabled()) {
                    LOG.debug(String.format("getFont('%s','%s') returns %s", format, postScriptName, info));
                }
                return info;
            }
            return null;
        }
    }

    @Test
    void testGetFontInvokesLogDebug() {
        TestFontMapper mapper = new TestFontMapper();

        FontInfo fontInfo = new FontInfo();
        fontInfo.setFormat(FontFormat.TYPE1);

        Map<String, FontInfo> fontMap = new HashMap<>();
        fontMap.put("testfont", fontInfo);

        try {
            java.lang.reflect.Field field = TestFontMapper.class.getDeclaredField("fontInfoByName");
            field.setAccessible(true);
            field.set(mapper, fontMap);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        mapper.getFont(FontFormat.TYPE1, "testfont");
    }
}

