    @Test
    void testConvertPngInvokesLogError() throws IOException {
        // Create real PDDocument
        PDDocument doc = new PDDocument();

        // Create PNGConverterState with invalid bit depth to trigger LOG.error
        PNGConverterState state = new PNGConverterState();
        Chunk ihdr = new Chunk();
        ihdr.bytes = new byte[100];
        ihdr.start = 0;
        // Set bit depth to invalid value (e.g., 3) to trigger the first LOG.error
        ihdr.bytes[8] = 3; // bitDepth = 3
        state.IHDR = ihdr;

        // Invoke the private method via reflection
        try {
            java.lang.reflect.Method method = PDImageXObject.class.getDeclaredMethod(
                "convertPng", PDDocument.class, PNGConverterState.class);
            method.setAccessible(true);
            method.invoke(null, doc, state);
        } catch (Exception e) {
            // Ignore exceptions - test only needs to reach the LOG.error call
        }

        doc.close();
    }

    // Helper classes to satisfy compilation
    static class PNGConverterState {
        Chunk IHDR;
        Chunk tRNS;
        int width;
        int height;
        int bitsPerComponent;
    }

    static class Chunk {
        byte[] bytes;
        int start;
    }
}

