        spaceWidthText = font.getSpaceWidth() * glyphSpaceToTextSpaceFactor;
    } catch (Exception exception) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
    {
        LOG.warn(exception, exception);
    }
