        BaseParser parser = new BaseParser(source);
        parser.parseCOSName();
    }

    private static class BaseParser {
        private final RandomAccessRead source;

        public BaseParser(RandomAccessRead source) {
            this.source = source;
        }

        protected COSName parseCOSName() throws IOException {
            readExpectedChar('/');
            java.io.ByteArrayOutputStream buffer = new java.io.ByteArrayOutputStream();
            int c = source.read();
            while (!isEndOfName(c)) {
                final int ch = c;
                if (ch == '#') {
                    int ch1 = source.read();
                    int ch2 = source.read();
                    if (isHexDigit(((char) (ch1))) && isHexDigit(((char) (ch2)))) {
                        String hex = Character.toString(((char) (ch1))) + ((char) (ch2));
                        try {
                            buffer.write(Integer.parseInt(hex, 16));
                        } catch (NumberFormatException e) {
                            throw new IOException(("Error: expected hex digit, actual='" + hex) + "'", e);
                        }
                        c = source.read();
                    } else {
                        if ((ch2 == (-1)) || (ch1 == (-1))) {
                            org.apache.commons.logging.LogFactory.getLog(getClass()).error("Premature EOF in BaseParser#parseCOSName");
                            c = -1;
                            break;
                        }
                        source.rewind(1);
                        c = ch1;
                        buffer.write(ch);
                    }
                } else {
                    buffer.write(ch);
                    c = source.read();
                }
            } 
            if (c != (-1)) {
                source.rewind(1);
            }
            return COSName.getPDFName(decodeBuffer(buffer));
        }

        private void readExpectedChar(char expected) throws IOException {
            int c = source.read();
            if (c != expected) {
                throw new IOException("Expected '" + expected + "' but got '" + (char)c + "'");
            }
        }

        private boolean isEndOfName(int c) {
            return c == -1 || c == ' ' || c == '\t' || c == '\n' || c == '\r' || 
                   c == '\f' || c == '>' || c == '<' || c == '[' || c == ']' || 
                   c == '(' || c == ')' || c == '/' || c == '%';
        }

        private boolean isHexDigit(char c) {
            return (c >= '0' && c <= '9') || (c >= 'A' && c <= 'F') || (c >= 'a' && c <= 'f');
        }

        private String decodeBuffer(java.io.ByteArrayOutputStream buffer) {
            return new String(buffer.toByteArray(), StandardCharsets.ISO_8859_1);
        }
    }
}

