    private static final Log LOG = Mockito.mock(Log.class);

    static {
        try {
            // Setup Cipher to return a value that will trigger the warn log
            Cipher cipherMock = Mockito.mock(Cipher.class);
            Mockito.when(Cipher.getMaxAllowedKeyLength("AES")).thenReturn(128);
        } catch (NoSuchAlgorithmException e) {
            // This won't happen with the mock
        }
