/**
 * Parse all compressed objects. The stream is closed after parsing.
 *
 * @return a map containing all parsed objects using the object number as key
 * @throws IOException
 * 		if there is an error while parsing the stream
 */
public Map<COSObjectKey, COSBase> parseAllObjects() throws IOException {
    Map<COSObjectKey, COSBase> allObjects = new HashMap<>();
    try {
        Map<Integer, Long> objectNumbers = privateReadObjectOffsets();
        // count the number of object numbers eliminating double entries
        long numberOfObjNumbers = objectNumbers.values().stream().distinct().count();
        // the usage of the index should be restricted to cases where more than one
        // object use the same object number.
        // there are malformed pdfs in the wild which would lead to false results if
        // pdfbox always relies on the index if available. In most cases the object number
        // is sufficient to choose the correct object
        boolean indexNeeded = objectNumbers.size() > numberOfObjNumbers;
        long currentPosition = source.getPosition();
        if ((firstObject > 0) && (currentPosition < firstObject)) {
            source.skip(firstObject - ((int) (currentPosition)));
        }
        int index = 0;
        for (Entry<Integer, Long> entry : objectNumbers.entrySet()) {
            COSObjectKey objectKey = getObjectKey(entry.getValue(), 0);
            // skip object if the index doesn't match
            if ((indexNeeded && (objectKey.getStreamIndex() > (-1))) && (objectKey.getStreamIndex() != index)) {
                index++;
                continue;
            }
            int finalPosition = firstObject + entry.getKey();
            currentPosition = source.getPosition();
            if ((finalPosition > 0) && (currentPosition < finalPosition)) {
                // jump to the offset of the object to be parsed
                source.skip(finalPosition - ((int) (currentPosition)));
            }
            // PATH: Test should invoke the next BaseParser.parseDirObject(...) [step in execution path]
            COSBase streamObject = parseDirObject();
            if (streamObject != null) {
                streamObject.setDirect(false);
            }
            allObjects.put(objectKey, streamObject);
            index++;
        }
    } finally {
        source.close();
        document = null;
    }
    return allObjects;
}

/**
 * This will parse a directory object from the stream.
 *
 * @return The parsed object.
 * @throws IOException
 * 		If there is an error during parsing.
 */
protected COSBase parseDirObject() throws IOException {
    try {
        recursionDepth++;
        if (recursionDepth > MAX_RECURSION_DEPTH) {
            throw new IOException(MAX_RECUSRION_MSG);
        }
        skipSpaces();
        char c = ((char) (source.peek()));
        switch (c) {
            case '<' :
                // pull off first left bracket
                source.read();
                // check for second left bracket
                c = ((char) (source.peek()));
                source.rewind(1);
                return c == '<' ? parseCOSDictionary(true) : parseCOSString();
            case '[' :
                // array
                return parseCOSArray();
            case '(' :
                return parseCOSString();
            case '/' :
                // name
                // PATH: Test should invoke the next BaseParser.parseCOSName(...) [step in execution path]
                return parseCOSName();
            case 'n' :
                // null
                readExpectedString(NULL, false);
                return COSNull.NULL;
            case 't' :
                readExpectedString(TRUE, false);
                return COSBoolean.TRUE;
            case 'f' :
                readExpectedString(FALSE, false);
                return COSBoolean.FALSE;
            case 'R' :
                source.read();
                return new COSObject(null);
            case ((char) (-1)) :
                return null;
            default :
                if (((Character.isDigit(c) || (c == '-')) || (c == '+')) || (c == '.')) {
                    return parseCOSNumber();
                }
                // This is not suppose to happen, but we will allow for it
                // so we are more compatible with POS writers that don't
                // follow the spec
                long startOffset = source.getPosition();
                String badString = readString();
                if (badString.isEmpty()) {
                    int peek = source.peek();
                    // we can end up in an infinite loop otherwise
                    throw new IOException(((((((((((("Unknown dir object c='" + c) + "' cInt=") + ((int) (c))) + " peek='") + ((char) (peek))) + "' peekInt=") + peek) + " at offset ") + source.getPosition()) + " (start offset: ") + startOffset) + ")");
                }
                // if it's an endstream/endobj, we want to put it back so the caller will see it
                if (ENDOBJ_STRING.equals(badString) || ENDSTREAM_STRING.equals(badString)) {
                    source.rewind(badString.getBytes(StandardCharsets.ISO_8859_1).length);
                } else {
                    LOG.warn(((((("Skipped unexpected dir object = '" + badString) + "' at offset ") + source.getPosition()) + " (start offset: ") + startOffset) + ")");
                    return this instanceof PDFStreamParser ? null : COSNull.NULL;
                }
        }
        return null;
    } finally {
        recursionDepth--;
    }
}

/**
 * This will parse a PDF name from the stream.
 *
 * @return The parsed PDF name.
 * @throws IOException
 * 		If there is an error reading from the stream.
 */
protected COSName parseCOSName() throws IOException {
    readExpectedChar('/');
    ByteArrayOutputStream buffer = new ByteArrayOutputStream();
    int c = source.read();
    while (!isEndOfName(c)) {
        final int ch = c;
        if (ch == '#') {
            int ch1 = source.read();
            int ch2 = source.read();
            // Prior to PDF v1.2, the # was not a special character.  Also,
            // it has been observed that various PDF tools do not follow the
            // spec with respect to the # escape, even though they report
            // PDF versions of 1.2 or later.  The solution here is that we
            // interpret the # as an escape only when it is followed by two
            // valid hex digits.
            if (isHexDigit(((char) (ch1))) && isHexDigit(((char) (ch2)))) {
                String hex = Character.toString(((char) (ch1))) + ((char) (ch2));
                try {
                    buffer.write(Integer.parseInt(hex, 16));
                } catch (NumberFormatException e) {
                    throw new IOException(("Error: expected hex digit, actual='" + hex) + "'", e);
                }
                c = source.read();
            } else {
                // check for premature EOF
                if ((ch2 == (-1)) || (ch1 == (-1))) {
                    LOG.error("Premature EOF in BaseParser#parseCOSName");
                    c = -1;
                    break;
                }
                source.rewind(1);
                c = ch1;
                buffer.write(ch);
            }
