                    LOG.debug((parentAttrKey + " => Handling DATA with encoding: ") + childEncodingAttr);
                    if ("HEX".equals(childEncodingAttr)) {
                        try (OutputStream os = stream.createRawOutputStream()) {
                            os.write(Hex.decodeHex(child.getTextContent()));
