package org.apache.pdfbox.rendering;

import org.junit.jupiter.api.Test;
import java.lang.reflect.Field;

public class PageDrawer_TilingPaintmethod_LogerrorFikaTest {

    @Test
    public void testTilingPaintStaticInitializer() throws Exception {
        // Trigger static initialization by accessing the class
        Class.forName("org.apache.pdfbox.rendering.TilingPaint");

        // Set system property to trigger NumberFormatException
        System.setProperty("pdfbox.rendering.tilingpaint.maxedge", "invalid_number");

        try {
            // Reset static field to force re-initialization
            Field maxEdgeField = TilingPaint.class.getDeclaredField("MAXEDGE");
            maxEdgeField.setAccessible(true);

            // Remove final modifier
            Field modifiersField = Field.class.getDeclaredField("modifiers");
            modifiersField.setAccessible(true);
            modifiersField.setInt(maxEdgeField, maxEdgeField.getModifiers() & ~java.lang.reflect.Modifier.FINAL);

            // Set to null to allow re-initialization
            maxEdgeField.set(null, null);

