        allPagesOverlayDocument = loadPDF(allPagesOverlayFilename);
    }
    if (allPagesOverlayDocument != null) {
        specificPageOverlayLayoutPageMap = createPageOverlayLayoutPageMap(allPagesOverlayDocument);
