    substitutes.computeIfAbsent(lowerCaseMatch, key -> new ArrayList<>()).add(replace);
}

private void addSubstitutes(String match, List<String> replacements) {
    substitutes.put(match.toLowerCase(Locale.ENGLISH), replacements);
}

