/**
 * Constructor for encrypted pdfs.
 *
 * @param source
 * 		input representing the pdf.
 * @param password
 * 		password to be used for decryption.
 * @param keyStore
 * 		key store to be used for decryption when using public key security
 * @param keyAlias
 * 		alias to be used for decryption when using public key security
 * @param streamCacheCreateFunction
 * 		a function to create an instance of the stream cache
 * @throws IOException
 * 		if the source data could not be read
 */
public COSParser(RandomAccessRead source, String password, InputStream keyStore, String keyAlias, StreamCacheCreateFunction streamCacheCreateFunction) throws IOException {
    super(source);
    this.password = password;
    this.keyAlias = keyAlias;
    fileLen = source.length();
    keyStoreInputStream = keyStore;
    init(streamCacheCreateFunction);
}

