package org.apache.pdfbox.pdfparser;

import org.apache.pdfbox.cos.COSObjectKey;
import org.apache.pdfbox.pdfparser.xref.XRefType;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class PDFParser_COSParserparseXrefTable_LogwarnFikaTest {

    @Mock
    private XRefTrailerResolver xrefTrailerResolver;

    @Test
    void testParseXrefTable() throws IOException {
        String input = "xref\ntrailer";
        InputStream stream = new ByteArrayInputStream(input.getBytes());
        RandomAccessSource source = new RandomAccessSource(stream);

        PDFParser parser = new PDFParser(source);
        parser.setXRefTrailerResolver(xrefTrailerResolver);

        parser.parseXrefTable(0);
    }

    private static class RandomAccessSource {
        private final InputStream stream;
        private int position = 0;
        private byte[] buffer = new byte[1024];
        private int bufferPos = 0;
        private int bufferLength = 0;

        RandomAccessSource(InputStream stream) {
            this.stream = stream;
        }

        char peek() throws IOException {
            ensureBuffer();
            if (bufferPos >= bufferLength) {
                return (char) -1;
            }
            return (char) buffer[bufferPos];
        }

        boolean isEOF() throws IOException {
            ensureBuffer();
            return bufferPos >= bufferLength;
        }

        void rewind(int length) {
            bufferPos = Math.max(0, bufferPos - length);
        }

        private void ensureBuffer() throws IOException {
            if (bufferPos >= bufferLength) {
                bufferLength = stream.read(buffer);
                bufferPos = 0;
            }
        }

        String readString() throws IOException {
            StringBuilder sb = new StringBuilder();
            while (true) {
                char c = peek();
                if (c == ' ' || c == '\n' || c == '\r' || c == (char) -1) {
                    break;
                }
                sb.append(c);
                bufferPos++;
            }
            return sb.toString();
        }

        String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            while (true) {
                char c = peek();
                if (c == (char) -1) {
                    break;
                }
                bufferPos++;
                if (c == '\n') {
                    break;
                }
                if (c != '\r') {
                    sb.append(c);
                }
            }
            return sb.toString();
        }

        void skipSpaces() throws IOException {
            while (true) {
                char c = peek();
                if (c != ' ' && c != '\t') {
                    break;
                }
                bufferPos++;
            }
        }

        boolean isDigit() throws IOException {
            char c = peek();
            return c >= '0' && c <= '9';
        }
    }

    private static class PDFParser {
        private final RandomAccessSource source;
        private XRefTrailerResolver xrefTrailerResolver;
        private final org.apache.commons.logging.Log LOG = org.apache.commons.logging.LogFactory.getLog(PDFParser.class);

        PDFParser(RandomAccessSource source) {
            this.source = source;
        }

        void setXRefTrailerResolver(XRefTrailerResolver resolver) {
            this.xrefTrailerResolver = resolver;
        }

        protected boolean parseXrefTable(long startByteOffset) throws IOException {
            if (source.peek() != 'x') {
                return false;
            }
            String xref = source.readString();
            if (!xref.trim().equals("xref")) {
                return false;
            }
            String str = source.readString();
            byte[] b = str.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1);
            source.rewind(b.length);
            xrefTrailerResolver.nextXrefObj(startByteOffset, XRefType.TABLE);
            if (str.startsWith("trailer")) {
                LOG.warn("skipping empty xref table");
                return false;
            }
            while (true) {
                String currentLine = source.readLine();
                String[] splitString = currentLine.split(" ");
                if (splitString.length != 2) {
                    LOG.warn("Unexpected XRefTable Entry: " + currentLine);
                    return false;
                }
                long currObjID;
                try {
                    currObjID = Long.parseLong(splitString[0]);
                } catch (NumberFormatException exception) {
                    LOG.warn("XRefTable: invalid ID for the first object: " + currentLine);
                    return false;
                }
                int count = 0;
                try {
                    count = Integer.parseInt(splitString[1]);
                } catch (NumberFormatException exception) {
                    LOG.warn("XRefTable: invalid number of objects: " + currentLine);
                    return false;
                }
                source.skipSpaces();
                for (int i = 0; i < count; i++) {
                    if (source.isEOF() || isEndOfName(source.peek())) {
                        break;
                    }
                    if (source.peek() == 't') {
                        break;
                    }
                    currentLine = source.readLine();
                    splitString = currentLine.split(" ");
                    if (splitString.length < 3) {
                        LOG.warn("invalid xref line: " + currentLine);
                        break;
                    }
                    if (splitString[splitString.length - 1].equals("n")) {
                        try {
                            long currOffset = Long.parseLong(splitString[0]);
                            if (currOffset > 0) {
                                int currGenID = Integer.parseInt(splitString[1]);
                                COSObjectKey objKey = new COSObjectKey(currObjID, currGenID);
                                xrefTrailerResolver.setXRef(objKey, currOffset);
                            }
                        } catch (IllegalArgumentException e) {
                            throw new IOException(e);
                        }
                    } else if (!splitString[2].equals("f")) {
                        throw new IOException("Corrupt XRefTable Entry - ObjID:" + currObjID);
                    }
                    currObjID++;
                    source.skipSpaces();
                }
                source.skipSpaces();
                if (!source.isDigit()) {
                    break;
                }
            }
            return true;
        }

        private boolean isEndOfName(char c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == '>' || c == '<' || c == '[' || c == ']' || c == '(' || c == ')' || c == '/' || c == '%';
        }
    }

    private interface XRefTrailerResolver {
        void nextXrefObj(long startByteOffset, XRefType type);
        void setXRef(COSObjectKey key, long offset);
    }
}

