// returns the stroking AWT Paint
private Paint getStrokingPaint() throws IOException {
    PDGraphicsState graphicsState = getGraphicsState();
    return // PATH: Test should invoke the next PageDrawer.getPaint(...) [step in execution path]
    applySoftMaskToPaint(getPaint(graphicsState.getStrokingColor()), graphicsState.getSoftMask());
}

/**
 * Returns an AWT paint for the given PDColor.
 *
 * @param color
 * 		The color to get a paint for. This can be an actual color or a pattern.
 * @return an AWT paint for the given PDColor
 * @throws IOException
 * 		if the AWT paint could not be created
 */
protected Paint getPaint(PDColor color) throws IOException {
    PDColorSpace colorSpace = color.getColorSpace();
    // PDFBOX-5782
    if (colorSpace == null) {
        LOG.error("colorSpace is null, will be rendered as transparency");
        return new Color(0, 0, 0, 0);
    } else if ((colorSpace instanceof PDSeparation) && "None".equals(((PDSeparation) (colorSpace)).getColorantName())) {
        // PDFBOX-4900: "The special colorant name None shall not produce any visible output"
        // TODO better solution needs to be found for all occurences where toRGB is called
        return new Color(0, 0, 0, 0);
    } else if (!(colorSpace instanceof PDPattern)) {
        float[] rgb = colorSpace.toRGB(color.getComponents());
        return new Color(clampColor(rgb[0]), clampColor(rgb[1]), clampColor(rgb[2]));
    } else {
        PDPattern patternSpace = ((PDPattern) (colorSpace));
        PDAbstractPattern pattern = patternSpace.getPattern(color);
        if (pattern instanceof PDTilingPattern) {
            PDTilingPattern tilingPattern = ((PDTilingPattern) (pattern));
            if (tilingPattern.getPaintType() == PDTilingPattern.PAINT_COLORED) {
                // colored tiling pattern
                // PATH: Test should invoke the next TilingPaintFactory.create(...) [step in execution path]
                return tilingPaintFactory.create(tilingPattern, null, null, xform);
            } else {
                // uncolored tiling pattern
                return tilingPaintFactory.create(tilingPattern, patternSpace.getUnderlyingColorSpace(), color, xform);
            }
        } else {
            PDShadingPattern shadingPattern = ((PDShadingPattern) (pattern));
            PDShading shading = shadingPattern.getShading();
            if (shading == null) {
                LOG.error("shadingPattern is null, will be filled with transparency");
                return new Color(0, 0, 0, 0);
            }
            return shading.toPaint(Matrix.concatenate(getInitialMatrix(), shadingPattern.getMatrix()));
        }
    }
}

Paint create(PDTilingPattern pattern, PDColorSpace colorSpace, PDColor color, AffineTransform xform) throws IOException {
    Paint paint = null;
    TilingPaintParameter tilingPaintParameter = new TilingPaintParameter(drawer.getInitialMatrix(), pattern.getCOSObject(), colorSpace, color, xform);
    WeakReference<Paint> weakRef = weakCache.get(tilingPaintParameter);
    if (weakRef != null) {
        // PDFBOX-4058: additional WeakReference makes gc work better
        paint = weakRef.get();
    }
    if (paint == null) {
        paint = new TilingPaint(drawer, pattern, colorSpace, color, xform);
        weakCache.put(tilingPaintParameter, new WeakReference<>(paint));
    }
    return paint;
}

/**
 * Creates a new tiling Paint. The parameters color and colorSpace must be null for a colored
 * tiling Paint (because it has its own colors), and non null for an uncolored tiling Paint.
 *
 * @param drawer
 * 		renderer to render the page
 * @param pattern
 * 		tiling pattern dictionary
 * @param colorSpace
 * 		color space for this tiling
 * @param color
 * 		color for this tiling
 * @param xform
 * 		device scale transform
 * @throws java.io.IOException
 * 		if something goes wrong while drawing the pattern
 */
(PageDrawer drawer, PDTilingPattern pattern, PDColorSpace colorSpace, PDColor color, AffineTransform xform) throws IOException {
    // pattern space -> user space
    patternMatrix = Matrix.concatenate(drawer.getInitialMatrix(), pattern.getMatrix());
    // PATH: Test should invoke the next TilingPaint.getAnchorRect(...) [step in execution path]
    Rectangle2D anchorRect = getAnchorRect(pattern);
    paint = new TexturePaint(getImage(drawer, pattern, colorSpace, color, xform, anchorRect), anchorRect);
}

/**
 * Returns the anchor rectangle, which includes the XStep/YStep and scaling.
 */
private Rectangle2D getAnchorRect(PDTilingPattern pattern) throws IOException {
    PDRectangle bbox = pattern.getBBox();
    if (bbox == null) {
        throw new IOException("Pattern /BBox is missing");
    }
    float xStep = pattern.getXStep();
    if (Float.compare(xStep, 0) == 0) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
    {
        LOG.warn("/XStep is 0, using pattern /BBox width");
        xStep = bbox.getWidth();
    }
    float yStep = pattern.getYStep();
    if (Float.compare(yStep, 0) == 0) {
        LOG.warn("/YStep is 0, using pattern /BBox height");
        yStep = bbox.getHeight();
    }
    float xScale = patternMatrix.getScalingFactorX();
    float yScale = patternMatrix.getScalingFactorY();
    float width = xStep * xScale;
    float height = yStep * yScale;
    if (Math.abs(width * height) > (MAXEDGE * MAXEDGE)) {
        // PDFBOX-3653: prevent huge sizes
        LOG.warn(((("Pattern surface larger than " + MAXEDGE) + " x ") + MAXEDGE) + ", will be clipped");
        LOG.warn((("width: " + width) + ", height: ") + height);
        LOG.warn((("XStep: " + xStep) + ", YStep: ") + yStep);
        LOG.warn("bbox: " + bbox);
        LOG.warn("pattern matrix: " + pattern.getMatrix());
        LOG.warn("concatenated matrix: " + patternMatrix);
        LOG.warn("increase the property 'pdfbox.rendering.tilingpaint.maxedge'");
        width = Math.min(MAXEDGE, Math.abs(width)) * Math.signum(width);
        height = Math.min(MAXEDGE, Math.abs(height)) * Math.signum(height);
        // TODO better solution needed
    }
    // returns the anchor rect with scaling applied
    return new Rectangle2D.Float(bbox.getLowerLeftX() * xScale, bbox.getLowerLeftY() * yScale, width, height);
}

