                "getAnchorRect", PDTilingPattern.class);
            method.setAccessible(true);
            Rectangle2D result = (Rectangle2D) method.invoke(drawer, pattern);
        } catch (Exception e) {
            // Ignore exceptions - test only needs to execute the method
        }
    }
}

