package org.apache.pdfbox.pdfparser;

import org.apache.pdfbox.pdfparser.BaseParser;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import java.io.ByteArrayOutputStream;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.lang.reflect.Field;

class COSParser_BaseParserdecodeBuffer_LogdebugFikaTest {

    @Test
    void testDecodeBufferTriggersLogDebug() throws Exception {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        byte[] invalidUtf8Bytes = {(byte) 0xC0, (byte) 0xC1}; // Invalid UTF-8 sequence
        buffer.writeBytes(invalidUtf8Bytes);

        BaseParser parser = new BaseParser();

        // Set UTF-8 decoder field
        Field utf8DecoderField = BaseParser.class.getDeclaredField("utf8Decoder");
        utf8DecoderField.setAccessible(true);
        utf8DecoderField.set(parser, StandardCharsets.UTF_8.newDecoder());

        // Set alternative charset field
        Field altCharsetField = BaseParser.class.getDeclaredField("ALTERNATIVE_CHARSET");
        altCharsetField.setAccessible(true);
        altCharsetField.set(parser, StandardCharsets.ISO_8859_1);

        // Set LOG field to a real logger (not mocked) so debug() gets called
        Field logField = BaseParser.class.getDeclaredField("LOG");
        logField.setAccessible(true);
        org.apache.commons.logging.Log realLog = org.apache.commons.logging.LogFactory.getLog(BaseParser.class);
        logField.set(parser, realLog);

        // Invoke private method via reflection
        java.lang.reflect.Method decodeBufferMethod = BaseParser.class.getDeclaredMethod(
                "decodeBuffer", ByteArrayOutputStream.class);
        decodeBufferMethod.setAccessible(true);

        try {
            decodeBufferMethod.invoke(parser, buffer);
        } catch (java.lang.reflect.InvocationTargetException e) {
            // Expected - method throws UnsupportedEncodingException
        }
    }
}

