/**
 * Constructor.
 *
 * @param parameters
 * 		Parameters for page drawing.
 * @throws IOException
 * 		If there is an error loading properties from the file.
 */
public PageDrawer(PageDrawerParameters parameters) throws IOException {
    super(parameters.getPage());
