import org.junit.jupiter.api.Test;
import java.io.ByteArrayOutputStream;
import java.io.IOException;

class PDFTextStrippermethod_LogdebugFikaTest4 {

    @Test
    void testLogDebugInvocation() throws IOException {
        // Create a minimal PDF document to process
        try (PDDocument document = new PDDocument()) {
            PDPage page = new PDPage(PDRectangle.A4);
            document.addPage(page);

            // Create PDFTextStripper instance
            PDFTextStripper stripper = new PDFTextStripper();

            // Set system property to trigger the static initializer block
            // that contains the target Log.debug() call
            System.setProperty("pdftextstripper.indent", "invalid");

            // Create a new instance after setting system property
            // This ensures the static block runs again in a new classloader context
            // We'll use a separate classloader approach
            ClassLoader originalClassLoader = Thread.currentThread().getContextClassLoader();
            try {
                // Create a new classloader to reload the class
                ClassLoader newClassLoader = new ClassLoader() {
                    @Override
                    public Class<?> loadClass(String name) throws ClassNotFoundException {
                        if (name.equals(PDFTextStripper.class.getName())) {
                            // Force reload of PDFTextStripper class
                            return findClass(name);
                        }
                        return super.loadClass(name);
                    }

                    @Override
                    protected Class<?> findClass(String name) throws ClassNotFoundException {
                        if (name.equals(PDFTextStripper.class.getName())) {
                            try {
                                // Get the class bytes
                                java.io.InputStream is = originalClassLoader.getResourceAsStream(
                                    "org/apache/pdfbox/text/PDFTextStripper.class");
                                byte[] bytes = is.readAllBytes();
                                return defineClass(name, bytes, 0, bytes.length);
                            } catch (IOException e) {
                                throw new ClassNotFoundException("Could not load class", e);
                            }
                        }
                        throw new ClassNotFoundException(name);
                    }
                };

                Thread.currentThread().setContextClassLoader(newClassLoader);

                // Load the class with new classloader to trigger static initializer
                Class<?> reloadedClass = newClassLoader.loadClass(PDFTextStripper.class.getName());

                // Create instance of reloaded class
                Object reloadedStripper = reloadedClass.getDeclaredConstructor().newInstance();

                // Extract text to ensure the static initializer runs
                ByteArrayOutputStream output = new ByteArrayOutputStream();
                ((PDFTextStripper) reloadedStripper).writeText(document, output);

            } catch (Exception e) {
                // Expected - the invalid property will cause NumberFormatException
                // which triggers the Log.debug() call in the static initializer
            } finally {
                Thread.currentThread().setContextClassLoader(originalClassLoader);
                // Clean up system property
                System.clearProperty("pdftextstripper.indent");
            }
        }
    }
}

