 * 		If the DA could not be parsed
 */
(COSString defaultAppearance, PDResources defaultResources) throws IOException // PATH: Test should invoke the next PDDefaultAppearanceString.processAppearanceStringOperators(...) [step in execution path]
{
    if (defaultAppearance == null) {
        throw new IllegalArgumentException("/DA is a required entry. " + "Please set a default appearance first.");
    }
    if (defaultResources == null) {
        throw new IllegalArgumentException("/DR is a required entry");
    }
    this.defaultResources = defaultResources;
    processAppearanceStringOperators(defaultAppearance.getBytes());
}

/**
 * Processes the operators of the given content stream.
 *
 * @param content
 * 		the content to parse.
 * @throws IOException
 * 		if there is an error reading or parsing the content stream.
 */
private void processAppearanceStringOperators(byte[] content) throws IOException {
    List<COSBase> arguments = new ArrayList<>();
    PDFStreamParser parser = new PDFStreamParser(content);
    Object token = parser.parseNextToken();
    while (token != null) {
        if (token instanceof Operator) {
            processOperator(((Operator) (token)), arguments);
            arguments = new ArrayList<>();
        } else {
            arguments.add(((COSBase) (token)));
        }
        token = parser.parseNextToken();
    } 
}

