        BaseParser parser = new BaseParser() {};

        // Create input that will trigger the Log.error path
        // We need a '#' followed by something that is NOT two valid hex digits
        // AND then an immediate EOF (-1) on the next read
        byte[] input = new byte[] {'/', '#', 'X'}; // 'X' is not a hex digit
        parser.source = new ByteArrayInputStream(input);

