        parser.parseCOSName();
    }

    // Minimal abstract base class implementation
    private static abstract class BaseParser {
        ByteArrayInputStream source;
        protected final org.apache.commons.logging.Log LOG = 
            org.apache.commons.logging.LogFactory.getLog(BaseParser.class);

        protected void readExpectedChar(char expected) throws IOException {
            int c = source.read();
            if (c != expected) {
                throw new IOException("Expected '" + expected + "' but got '" + (char)c + "'");
            }
        }

        protected boolean isEndOfName(int c) {
            return c == -1 || Character.isWhitespace(c) || c == '>' || c == '<' || c == '[' || c == ']' || c == '/' || c == '(' || c == ')';
        }

        protected boolean isHexDigit(char c) {
            return (c >= '0' && c <= '9') || (c >= 'A' && c <= 'F') || (c >= 'a' && c <= 'f');
        }

        protected String decodeBuffer(ByteArrayOutputStream buffer) {
            return new String(buffer.toByteArray());
        }

        protected abstract COSName parseCOSName() throws IOException;
    }

    // Minimal ByteArrayOutputStream for compilation
    private static class ByteArrayOutputStream {
        private byte[] buffer = new byte[0];

        public void write(int b) {
            byte[] newBuffer = new byte[buffer.length + 1];
            System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
            newBuffer[buffer.length] = (byte)b;
            buffer = newBuffer;
        }

        public byte[] toByteArray() {
            return buffer;
        }
    }
}

