PDDefaultAppearanceString getDefaultAppearanceString() throws IOException {
    COSBase base = getInheritableAttribute(COSName.DA);
    COSString da = null;
    if (base instanceof COSString) {
        da = ((COSString) (base));
    }
    PDResources dr = getAcroForm().getDefaultResources();
