package org.apache.pdfbox.contentstream;

import org.apache.pdfbox.contentstream.PDFStreamEngine;
import org.apache.pdfbox.pdmodel.graphics.pattern.PDTilingPattern;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.contentstream.PDFStreamEngine.TilingPaint;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.awt.geom.Rectangle2D;
import java.io.IOException;

class PDFStreamEngine_TilingPaintgetAnchorRect_LogwarnFikaTest2 {

    @Test
    void testGetAnchorRectInvokesLogWarn() throws IOException {
        // Create a real TilingPaint instance
        PDFStreamEngine engine = new PDFStreamEngine();
        TilingPaint tilingPaint = engine.new TilingPaint();

        // Create mock PDTilingPattern with xStep = 0 to trigger the Log.warn call
        PDTilingPattern pattern = Mockito.mock(PDTilingPattern.class);
        PDRectangle bbox = new PDRectangle(100, 200);

        Mockito.when(pattern.getBBox()).thenReturn(bbox);
        Mockito.when(pattern.getXStep()).thenReturn(0f);
        Mockito.when(pattern.getYStep()).thenReturn(10f);
        Mockito.when(pattern.getMatrix()).thenReturn(null);

        // Set patternMatrix scaling factors
        java.lang.reflect.Field patternMatrixField;
        try {
            patternMatrixField = TilingPaint.class.getDeclaredField("patternMatrix");
            patternMatrixField.setAccessible(true);

            // Create a simple matrix that returns reasonable scaling factors
            Object mockMatrix = Mockito.mock(Class.forName("org.apache.pdfbox.util.Matrix"));
            Mockito.when(mockMatrix.getClass().getMethod("getScalingFactorX").invoke(mockMatrix))
                   .thenReturn(1f);
            Mockito.when(mockMatrix.getClass().getMethod("getScalingFactorY").invoke(mockMatrix))
                   .thenReturn(1f);

            patternMatrixField.set(tilingPaint, mockMatrix);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Set MAXEDGE to a large value to avoid triggering the second warn block
        try {
            java.lang.reflect.Field maxEdgeField = TilingPaint.class.getDeclaredField("MAXEDGE");
            maxEdgeField.setAccessible(true);
            maxEdgeField.set(tilingPaint, 1000000f);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Invoke the private method using reflection
        try {
            java.lang.reflect.Method method = TilingPaint.class.getDeclaredMethod(
                "getAnchorRect", PDTilingPattern.class);
            method.setAccessible(true);
            Rectangle2D result = (Rectangle2D) method.invoke(tilingPaint, pattern);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}

