            float fontWidth = font.getWidthFromFont(code);
            if (((displacement.getX() > 0)// PDFBOX-5611: ignore zero widths
             && (fontWidth > 0))// ignore spaces
             && (Math.abs(fontWidth - (displacement.getX() * 1000)) > 1.0E-4)) {
                float pdfWidth = displacement.getX() * 1000;
                at.scale(pdfWidth / fontWidth, 1);
            }
        }
        // render glyph
        Shape glyph = at.createTransformedShape(path);
        if (isContentRendered()) {
            if (renderingMode.isFill()) {
                graphics.setComposite(state.getNonStrokingJavaComposite());
                graphics.setPaint(getNonStrokingPaint());
                setClip();
                graphics.fill(glyph);
            }
            if (renderingMode.isStroke()) {
                graphics.setComposite(state.getStrokingJavaComposite());
                // PATH: Test should invoke the next PageDrawer.getStrokingPaint(...) [step in execution path]
                graphics.setPaint(getStrokingPaint());
                graphics.setStroke(getStroke());
                setClip();
                graphics.draw(glyph);
            }
        }
        if (renderingMode.isClip()) {
            textClippings.add(glyph);
        }
    }
